; Generated by disasm_z80
; Source: CPM_BDOS
; Range:  $DC00-$E9FF  (3584 bytes)

;
; ===========================================================================
; 60K BDOS  -- CP/M 2.2 BDOS adapted to the Apple II Language Card (LC)
; ===========================================================================
; This is the standard CP/M 2.2 BDOS (serial BD16000 / 14D40, identical to the
; 44K sysimg_223 BDOS) but RELOCATED and BANK-WOVEN for the 60K LC system.
;
; STRUCTURE (standard CP/M 2.2 BDOS layout, all present):
;   $DC00  BD 16 00 01 4D 40   serial number (== 44K BDOS, unchanged)
;   $DC06  C3 11 DC            JP BDOS_ENTRY   = BDOS primary entry (== 44K JP $9C11)
;   $DC09  jump/vector quad ($DCA5,$DCB2,$DCB7,$DCBC)
;   $DC11  dispatch preamble (see DELTA below)
;   $DC53  41-entry function-pointer table (BDOS funcs 0..40 / $00..$28)
;   ...    FCB / file primitives, directory, disk I/O, console redirection.
;
; LANGUAGE-CARD WINDOW MAP (running system):
;   Z-80 $Bxxx..$DFFF  -> Apple $Dxxx..$FFFF  (the 16K Language Card)
;     so Z-80 $DCxx -> Apple $FCxx (UPPER LC),  Z-80 $Bxxx -> Apple $Dxxx (LOWER LC)
;   Z-80 $E08B/$E083   -> Apple $C08B/$C083    (LC soft-switches in the I/O window)
;     $C08B = read-RAM / write-RAM, bank1     $C083 = read-RAM / write-RAM, bank2
;
; THE SPLIT (dispatch table at $DC53, 41 entries):
;   - 11 funcs live in the UPPER LC at $DCxx-$DFxx  (Apple $FCxx-$FFxx) -- the
;     same window the dispatcher itself occupies; these are the BIOS-adjacent
;     console/line-edit/search helpers.
;   -  3 entries are delegated straight to the BIOS at $FA03/$FA0F/$FA12
;     (WBOOT + 2 console BIOS calls).
;   - 27 funcs live in the LOWER LC at $Bxxx (Apple $Dxxx) -- the bulk of the
;     FCB/file/directory/disk machinery was relocated DOWN into the lower bank.
;   BDOS scratch/zero-page-equivalent variables sit at $BFxx (Apple $DFxx);
;     referenced ~130 times across the body.
;
; LANGUAGE-CARD BANK-SWITCH ACCESSES (13 total, all WRITES; no ROM-read modes):
;   $DC11  LD ($E08B),A   entry: bank-in LC (Apple $C08B)
;   $DC3F  LD ($E083),A   funcs <12: select bank2 (Apple $C083)
;   $DD5B  LD ($E08B),A   $DD64  LD ($E083),A   (helper bank flip)
;   $DF1C/$DF20/$DF28     LD ($E083),A   (lower-LC trampoline glue)
;   $DF36  LD ($E08B),A   $DF3C  LD ($E083),A
;   $DF41/$DF45  LD ($E08B),A           (epilogue: bank-out / restore on exit)
;   $DF63  LD ($E083),A   $DF81  LD ($E083),A
;   => 5x $E08B (Apple $C08B), 8x $E083 (Apple $C083).
;
; DISPATCH-PREAMBLE DELTA vs 44K BDOS (sysimg_223 off 0xD00, entry $9C11):
;   44K $9C11:  EB            EX DE,HL
;               22 43 9F      LD ($9F43),HL    ; save DE param, NO banking
;               ... 32 E0 A9 / 32 DE A9        ; plain RAM scratch ($A9xx)
;   60K $DC11:  32 8B E0      LD ($E08B),A     ; <-- inserted LC BANK-IN first
;               ED 53 11 DF   LD (BDOS_PARAM_PTR),DE    ; save DE param (LC scratch)
;               32 E3 BF      LD (DRV_SELECT_ARG),A     ; mirror to lower-LC scratch
;               ... 31 0F DF  LD SP,BDOS_STACK_TOP      ; private stack in LC
;               21 45 DF / E5 PUSH $DF45       ; return -> bank-OUT epilogue
;               FE 0C / 32 83 E0  (func<12) LD ($E083),A  ; bank2 select
;   Both keep the SAME func-count guard (CP $29 = 41 functions) and the same
;   table-indexed JP (HL).  The 60K version simply wraps every call in a
;   bank-in (entry) / bank-out ($DF45 epilogue) envelope and scatters the body
;   across the two LC banks; the 44K version runs entirely in flat RAM.
; ===========================================================================

    IFNDEF CPM60_LINK  ; [link] master defines CPM60_LINK and owns this; standalone keeps it
    DEVICE NOSLOT64K
    ENDIF

; -- External symbols --
WBOOTV            EQU $0000               ; Warm-boot vector — JP WBOOT in BIOS. Touching it causes a CP/M warm boot.
IOBYTE_ADDR               EQU $0003               ; [DOC S&HD 2-18..2-21] I/O assignment byte at $0003: maps four logical
                                             ; devices to physical devices via four 2-bit fields -- CONSOLE (bits 0-1),
                                             ; READER (bits 2-3), PUNCH (bits 4-5), LIST (bits 6-7). Read/written by BDOS
                                             ; funcs 7 (Get I/O Byte) and 8 (Set I/O Byte); selects which I/O Vector Table
                                             ; entry (#1 vs #2) the BIOS console/reader/punch/list routines use.
WBOOT                EQU $FA03               ; BIOS entry 1  -- warm boot (on SoftCard 2.23: jumps to $FAB8)
CONST                EQU $FA06               ; BIOS entry 2  -- console status
CONIN                EQU $FA09               ; BIOS entry 3  -- console input
CONOUT               EQU $FA0C               ; BIOS entry 4  -- console output
LIST                 EQU $FA0F               ; BIOS entry 5  -- printer (LIST device) output
PUNCH                EQU $FA12               ; BIOS entry 6  -- punch device output
READER               EQU $FA15               ; BIOS entry 7  -- reader device input
HOME                 EQU $FA18               ; BIOS entry 8  -- seek drive to track 0
SELDSK               EQU $FA1B               ; BIOS entry 9  -- select drive, returns its DPH
SETTRK               EQU $FA1E               ; BIOS entry 10 -- set track for the next access
SETSEC               EQU $FA21               ; BIOS entry 11 -- set sector for the next access
SETDMA               EQU $FA24               ; BIOS entry 12 -- set the DMA (transfer) address
READ                 EQU $FA27               ; BIOS entry 13 -- read one 128-byte record
WRITE                EQU $FA2A               ; BIOS entry 14 -- write one 128-byte record
SECTRAN              EQU $FA30               ; BIOS entry 16 -- logical-to-physical sector translate
; -- Language-Card bank-select soft switches (Z-80 $E08x -> Apple $C08x I/O window) --
LC_BANK1             EQU $E08B               ; select LC read/write RAM, bank 1 (Apple $C08B)
LC_BANK2             EQU $E083               ; select LC read/write RAM, bank 2 (Apple $C083)

    IFNDEF CPM60_LINK  ; [link] master defines CPM60_LINK and owns this; standalone keeps it
    ORG $DC00
    ELSE
    DISP $DC00         ; linked: upper-bank labels at run $DC00, emit at the master's file pos
    ENDIF

BDOS_IMAGE_HEADER:
        CP L
        LD D,$00
        LD BC,$404D
        JP BDOS_ENTRY
        DEFW    BDOS_ERROR
        DEFB    $B2,$DC,$B7,$DC,$BC,$DC
; [DOC CPMREF 3-44] BDOS primary entry. Callers reach it via the JP at $0005 (the word at $0006 is
;       this entry / top of TPA). Function # is in C and the info address (or single byte) in DE/E.
;       Per the manual the BDOS switches to its own local stack on each call (here BDOS_STACK_TOP), and
;       a zero value is returned when the function number is out of range. The LC_RDWR_* bank
;       accesses and LC scratch ($BFxx) are this 60K build's Language-Card wrapper, not manual facts.
BDOS_ENTRY:
        LD (LC_BANK1),A
        LD (BDOS_PARAM_PTR),DE           ; save the DE info-address parameter
        LD A,E
        LD (DRV_SELECT_ARG),A
        LD HL,WBOOTV
        LD (BDOS_RETVAL),HL              ; pre-seed return value = 0 (out-of-range default)
        LD (BDOS_SAVED_SP),SP            ; save caller's stack pointer
        LD SP,BDOS_STACK_TOP             ; switch to the BDOS local stack
        XOR A
        LD (DRV_SAVED_FCB_BYTE),A
        LD (DRV_RESTORE_FLAG),A
        LD (DEFERRED_COPY_FLAG),A
        LD HL,BDOS_BANK_OUT_EPILOG
        PUSH HL
        LD A,C                           ; 79    A = function number
        CP $29                           ; range check (41 dispatch entries; CP/M 2.2 defines 0-36)
        RET NC                           ; D0    out of range -> return the pre-seeded zero
        CP $0C
        JR NC,BDOS_ENTRY_1
        LD (LC_BANK2),A
BDOS_ENTRY_1:
        LD C,E
        LD HL,BDOS_DISPATCH_TBL
        LD E,A
        LD D,$00
        ADD HL,DE
        ADD HL,DE
        LD E,(HL)
        INC HL
        LD D,(HL)
        LD HL,(BDOS_PARAM_PTR)
        EX DE,HL
        JP (HL)
; [DOC CPMREF 3-44/3-76] BDOS function-pointer dispatch table, indexed by the function
;       number passed in C (entry N = function N, two bytes each). The CP/M 2.2 BDOS defines
;       functions 0-36 ($00-$24); entries 37-40 ($25-$28) have no manual-defined function in
;       CP/M 2.2 (the 41-entry / CP $29 guard is this 60K build's table size, not a manual fact).
;       Call convention: function # in C, info address (or single byte) in DE/E; byte results
;       in A, word results in HL, with A=L and B=H on return.
BDOS_DISPATCH_TBL:
        DEFW    WBOOT                    ; fn 0  System Reset (warm boot; re-login drive A)
        DEFW    F_CONIN_H                ; fn 1  Console Input  -> A=char (echoed)
        DEFW    F_CONOUT_H               ; fn 2  Console Output (E=char; expands tabs)
        DEFW    F_READERIN_H             ; fn 3  Reader Input (RDR:) -> A=char
        DEFW    PUNCH                    ; fn 4  Punch Output (PUN:; E=char)
        DEFW    LIST                     ; fn 5  List Output (LST:; E=char)
        DEFW    F_DIRECTIO_H             ; fn 6  Direct Console I/O (E=$FF in / char out; raw)
        DEFW    F_GETIOB_H               ; fn 7  Get I/O Byte -> A=IOBYTE_ADDR ($0003)
        DEFW    F_SETIOB_H               ; fn 8  Set I/O Byte (E=IOBYTE_ADDR)
        DEFW    F_PRINTSTR_H             ; fn 9  Print String (DE='$'-terminated)
        DEFW    F_READCONBUF_H           ; fn 10 Read Console Buffer (DE=buffer; line editor)
        DEFW    F_CONSTAT_H              ; fn 11 Get Console Status -> A=$FF/$00
        DEFW    $BEA3                    ; fn 12 Return Version Number -> HL ($0022 for 2.2)
        DEFW    $BEA8                    ; fn 13 Reset Disk System (all R/W, select A, DMA=$0080)
        DEFW    $BE47                    ; fn 14 Select Disk (E=0..15 = A..P)
        DEFW    $BEC0                    ; fn 15 Open File (DE=FCB) -> A=dir code/$FF
        DEFW    $BEC6                    ; fn 16 Close File (DE=FCB) -> A=dir code/$FF
        DEFW    $BECC                    ; fn 17 Search for First (DE=FCB) -> A=dir code
        DEFW    $BEEB                    ; fn 18 Search for Next -> A=dir code (255=no more)
        DEFW    $BEFC                    ; fn 19 Delete File (DE=FCB) -> A=dir code/255
        DEFW    $BF05                    ; fn 20 Read Sequential (DE=FCB) -> A=err (0 ok)
        DEFW    $BF0B                    ; fn 21 Write Sequential (DE=FCB) -> A=err (0 ok)
        DEFW    $BF11                    ; fn 22 Make File (DE=FCB) -> A=dir code/$FF
        DEFW    $BF17                    ; fn 23 Rename File (DE=FCB) -> A=dir code/$FF
        DEFW    $BF20                    ; fn 24 Return Login Vector -> HL=login bit-vector
        DEFW    $BF25                    ; fn 25 Return Current Disk -> A=current disk (0-15)
        DEFW    $BF2B                    ; fn 26 Set DMA Address (DE=DMA addr; default $0080)
        DEFW    $BF32                    ; fn 27 Get Addr (Alloc) -> HL=ALLOC vector base
        DEFW    $B79B                    ; fn 28 Write Protect Disk (temp R/O, current drive)
        DEFW    $BF37                    ; fn 29 Get R/O Vector -> HL=R/O bit-vector
        DEFW    $BF3C                    ; fn 30 Set File Attributes (DE=FCB; sets t1' R/O, t2' SYS)
        DEFW    $BF45                    ; fn 31 Get Addr (Disk Parms) -> HL=DPB address
        DEFW    $BF4C                    ; fn 32 Set/Get User Code (E=$FF get / code set)
        DEFW    $BF5F                    ; fn 33 Read Random (DE=FCB) -> A=return code
        DEFW    $BF65                    ; fn 34 Write Random (DE=FCB) -> A=return code (+05 dir full)
        DEFW    $BF6B                    ; fn 35 Compute File Size (DE=FCB) -> r0,r1,r2 set
        DEFW    $BE31                    ; fn 36 Set Random Record (DE=FCB) -> r0,r1,r2 set
        DEFW    $BF71                    ; fn 37 -- not a CP/M 2.2 manual function (version-specific entry)
        DEFW    BDOS_RET_NOP             ; fn 38 -- not a CP/M 2.2 manual function; stub -> RET (BDOS_RET_NOP)
        DEFW    BDOS_RET_NOP             ; fn 39 -- not a CP/M 2.2 manual function; stub -> RET (BDOS_RET_NOP)
        DEFW    $BF92                    ; fn 40 -- not a CP/M 2.2 manual function (version-specific entry)
; [DOC CPMREF 3-36/3-37] BDOS run-time error reporter. Prints "Bdos Err On x: <error>"
;       where x is the drive letter and <error> is one of BAD SECTOR (controller R/W error),
;       SELECT (drive outside the valid range; reboots after console input), or R/O (write to
;       a read-only / changed disk; warm start after console input). The error code in C
;       selects which message: the embedded $-terminated strings are "Bdos Err On  : $" ($DCC5),
;       "Bad Sector$" ($DCD0), "Select$" ($DCDB), "File R/O$" ($DCE2); $C6 $41 = ADD A,'A'
;       converts the drive number to its letter.
BDOS_ERROR:
        DEFB    $21,$D5,$DC,$CD,$F0,$DC,$FE,$03,$C2,$41,$DF,$18,$10,$21,$E0,$DC
        DEFB    $18,$08,$21,$EC,$DC,$18,$03,$21,$E7,$DC,$CD,$F0,$DC,$C3,$00,$00
        DEFB    $42,$64,$6F,$73,$20,$45,$72,$72,$20,$4F,$6E,$20,$20,$3A,$20,$24 ; "Bdos Err On  : $"
        DEFB    $42,$61,$64,$20,$53,$65,$63,$74,$6F,$72,$24,$53,$65,$6C,$65,$63 ; "Bad Sector$" "Selec"
        DEFB    $74,$24,$46,$69,$6C,$65,$20,$52,$2F,$4F,$24,$E5,$CD ; "t$" "File R/O$"
        DEFW    CON_CRLF
        DEFB    $3A,$10,$DF,$C6,$41,$32,$D1,$DC,$01,$C5,$DC,$CD
        DEFW    CON_PRINT_STR
        DEFB    $C1,$CD
        DEFW    CON_PRINT_STR
; ----------------------------------------------------------------------
; CON_GETC_OR_RAW -- return the 1-char type-ahead if present, else read raw console input.
;   In: CON_PENDING_CHAR = pending look-ahead char (0 if none).
;   Out: A = next console character; CON_PENDING_CHAR cleared if it supplied the byte.
;   Clobbers: AF, HL.
;   Algorithm: if CON_PENDING_CHAR nonzero, consume it (write 0 back) and return; otherwise
;              tail-jump to the BIOS CONIN vector ($FA09) for a fresh key.
;   [RE] Single-byte console un-get buffer used by the line editor and F_CONIN_H. Twin of the
;        44K CON_GETC_OR_RAW (identical logic; runs in the upper LC bank here).
; ----------------------------------------------------------------------
CON_GETC_OR_RAW:
        LD HL,CON_PENDING_CHAR
        LD A,(HL)
        LD (HL),$00
        OR A
        RET NZ
        JP CONIN
; ----------------------------------------------------------------------
; F_CONIN_RAW -- read one console char, echoing it unless it is a control char.
;   In: none.  Out: A = character read.  Clobbers: AF, BC, HL.
;   Algorithm: fetch a char (CON_GETC_OR_RAW); test it with LC_BANK1_CALL_ISCTRL (banks the
;              lower LC in and calls IS_CTRL_CHAR at $B5C0); on carry (unhandled control) skip
;              the echo; otherwise echo the char via F_CONOUT_H, preserving it in A.
;   [RE] Backs BDOS function 1 (Console Input with echo). Twin of the 44K F_CONIN_RAW; the
;        60K wraps the IS_CTRL_CHAR test in a bank trampoline because that helper lives in the
;        lower LC bank.
; ----------------------------------------------------------------------
F_CONIN_RAW:
        CALL CON_GETC_OR_RAW
        CALL LC_BANK1_CALL_ISCTRL
        RET C
        PUSH AF
        LD C,A
        CALL F_CONOUT_H
        POP AF
        RET
; ----------------------------------------------------------------------
; CON_POLL_STATUS -- console-status poll that also traps Ctrl-S/Ctrl-C while idle.
;   In: CON_PENDING_CHAR = type-ahead char (nonzero => a key is already pending).
;   Out: A = 1 if a character is ready, 0 if not.  Clobbers: AF.
;   Algorithm: if a char is already buffered, report ready; else call the BIOS console-status
;              vector (CONST $FA06) and mask bit 0. If a key is down, peek it (CONIN $FA09):
;              Ctrl-S ($13) stalls -- the follow-up key Ctrl-C ($03) warm-boots via JP 0; any
;              other key is stashed in CON_PENDING_CHAR (CON_POLL_STASH) and reported ready.
;   [RE] Backs the BDOS console-status / flow-control behaviour. Twin of the 44K CON_POLL_STATUS.
; ----------------------------------------------------------------------
CON_POLL_STATUS:
        LD A,(CON_PENDING_CHAR)
        OR A
        JR NZ,CON_STATUS_READY
        CALL CONST
        AND $01
; CON_POLL_STATUS_1 -- fall-through re-entry inside CON_POLL_STATUS: RET Z when no key is down,
;   else read and test the pending key. Not a separate call target (dead auto-name kept local).
;   [RE] Local of CON_POLL_STATUS.
CON_POLL_STATUS_1:
        RET Z
        CALL CONIN
        CP $13
        JR NZ,CON_POLL_STASH
        CALL CONIN
        CP $03
        JP Z,WBOOTV
        XOR A
        RET
; ----------------------------------------------------------------------
; CON_POLL_STASH -- stash the just-read key as type-ahead and report 'ready'.
;   In: A = key character to hold.  Out: A = 1 (ready).  Clobbers: A.
;   Algorithm: store A into CON_PENDING_CHAR, then fall into the A:=1 tail (CON_STATUS_READY).
;   [RE] Twin of the 44K CON_POLL_STASH.
; ----------------------------------------------------------------------
CON_POLL_STASH:
        LD (CON_PENDING_CHAR),A
; ----------------------------------------------------------------------
; CON_STATUS_READY -- return A=1, the 'character is ready' status result.
;   In: none.  Out: A=1.  Clobbers: A.  [RE] Shared tail of CON_POLL_STATUS (44K twin).
; ----------------------------------------------------------------------
CON_STATUS_READY:
        LD A,$01
        RET
; ----------------------------------------------------------------------
; CON_PUT_COL -- output one char to the console, tracking column and honouring Ctrl-S.
;   In: C = character to print.
;   Out: char sent to console (and to the list device if CON_LIST_ECHO set); the column cell is
;        updated for the char.  Clobbers: AF, HL (BC preserved across the BIOS calls).
;   Algorithm: unless the redisplay-suppress flag (CON_SAVED_COL) is set, poll for Ctrl-S/Ctrl-C
;              (CON_POLL_STATUS) then send C to the BIOS CONOUT ($FA0C) and, if CON_LIST_ECHO is
;              set, to the BIOS LIST ($FA0F). Then fall into LC_BANK1_CALL_TRACKCOL to update the
;              column via the lower-bank CON_TRACK_COL ($B5D5).
;   [RE] Core char output + column bookkeeping. Twin of the 44K CON_PUT_COL; column tracking is
;        split into the lower LC bank here.
; ----------------------------------------------------------------------
CON_PUT_COL:
        LD A,(CON_SAVED_COL)
        OR A
        JR NZ,LC_BANK1_CALL_TRACKCOL
        PUSH BC
        CALL CON_POLL_STATUS
        POP BC
        PUSH BC
        CALL CONOUT
        POP BC
        PUSH BC
; CON_PUT_COL_LIST -- fall-through inside CON_PUT_COL: if CON_LIST_ECHO is set, mirror the char
;   to the BIOS LIST device ($FA0F). Not a separate call target (dead auto-name kept local).
;   [RE] Local of CON_PUT_COL.
CON_PUT_COL_LIST:
        LD A,(CON_LIST_ECHO)
        OR A
        CALL NZ,LIST
        POP BC
; ----------------------------------------------------------------------
; LC_BANK1_CALL_TRACKCOL -- bank the lower LC in and update the console column counter.
;   In: C = char just emitted.  Out: CON_COL adjusted; bank2 restored on return.
;   Clobbers: AF, HL (per CON_TRACK_COL).
;   Algorithm: LD (LC_BANK1),A selects LC read/write bank1 (Apple $C08B) so the lower-bank code
;              at $B5D5 is visible, CALL CON_TRACK_COL (CON_TRACK_COL), then JP LC_BANK2_RET to restore
;              bank2 and RET.
;   [RE] 60K bank-switch trampoline (no 44K counterpart -- 44K tracks the column inline).
; ----------------------------------------------------------------------
LC_BANK1_CALL_TRACKCOL:
        LD (LC_BANK1),A
        CALL CON_TRACK_COL
        JP LC_BANK2_RET
        DEFB    $32
        DEFW    LC_BANK2
        DEFB    $FE,$0A,$C0,$36,$00,$C9
; ----------------------------------------------------------------------
; CON_PUT_VISIBLE -- output a char, expanding non-tab control codes as '^X'.
;   In: C = character.  Out: char(s) sent via CON_PUT_COL / F_CONOUT_H.  Clobbers: AF.
;   Algorithm: test the char with LC_BANK1_CALL_ISCTRL (lower-bank IS_CTRL_CHAR); if it is a
;              handled char (carry clear) print it normally through F_CONOUT_H; otherwise emit
;              '^' ($5E) via CON_PUT_COL then the char OR'd with $40, so e.g. Ctrl-A shows '^A'.
;   [RE] Visible-control echo used by the line editor's buffer redisplay. Twin of 44K
;        CON_PUT_VISIBLE.
; ----------------------------------------------------------------------
CON_PUT_VISIBLE:
        LD A,C
        CALL LC_BANK1_CALL_ISCTRL
        JR NC,F_CONOUT_H
        PUSH AF
        LD C,$5E
        CALL CON_PUT_COL
        POP AF
        OR $40
        LD C,A
; ----------------------------------------------------------------------
; F_CONOUT_H -- BDOS console-output handler (function 2) with tab expansion.
;   In: C = character to print.  Out: character emitted; TAB expands to the next 8-column stop.
;   Clobbers: AF.
;   Algorithm: if C != TAB ($09) just print it via CON_PUT_COL; if TAB, fall into CONOUT_TAB_FILL
;              to emit spaces until CON_COL is a multiple of 8.
;   [DOC CPMREF 3-44] BDOS function 2 (Console Output). Twin of 44K F_CONOUT_H; dispatch fn 2.
; ----------------------------------------------------------------------
F_CONOUT_H:
        LD A,C
        CP $09
        JR NZ,CON_PUT_COL
; ----------------------------------------------------------------------
; CONOUT_TAB_FILL -- emit spaces until the column reaches the next 8-stop (tab expand).
;   In: CON_COL = current column.  Out: spaces printed until (column & 7)==0.  Clobbers: AF, C.
;   Algorithm: output a space via CON_PUT_COL, re-read CON_COL, loop while low 3 bits are set.
;   [RE] Tab-expansion loop of F_CONOUT_H (44K twin).
; ----------------------------------------------------------------------
CONOUT_TAB_FILL:
        LD C,$20
        CALL CON_PUT_COL
        LD A,(CON_COL)
        AND $07
        JR NZ,CONOUT_TAB_FILL
        RET
; ----------------------------------------------------------------------
; CON_BACKSPACE -- erase the last echoed character (BS, space, BS).
;   In: none.  Out: cursor moved left one cell, char blanked on screen.  Clobbers: AF, C.
;   Algorithm: emit BS via CON_BS_OUT, then a space to the BIOS CONOUT ($FA0C), then fall into
;              CON_BS_OUT for the trailing BS so the previous glyph is overwritten with a blank.
;   [RE] Twin of the 44K CON_BACKSPACE (44K's CON_ERASE_CHAR before de-aliasing).
; ----------------------------------------------------------------------
CON_BACKSPACE:
        CALL CON_BS_OUT
        LD C,$20
        CALL CONOUT
; ----------------------------------------------------------------------
; CON_BS_OUT -- send a single backspace ($08) to the console.
;   In: none.  Out: BS emitted via the BIOS CONOUT vector ($FA0C).  Clobbers: C.
;   [RE] Tail-call helper; also the leading and trailing BS of CON_BACKSPACE. Twin of 44K
;        CON_BS_OUT.
; ----------------------------------------------------------------------
CON_BS_OUT:
        LD C,$08
        JP CONOUT
; ----------------------------------------------------------------------
; CON_RETYPE_LINE -- echo '#' + CR/LF and reposition for a line-kill / retype (Ctrl-U/Ctrl-R).
;   In: CON_COL = current column; CON_LINE_START_COL = line-start column.
;   Out: '#' printed on a fresh line; cursor advanced with spaces back to the start column.
;   Clobbers: AF, C, HL.
;   Algorithm: print '#' ($23) via CON_PUT_COL, CON_CRLF, then fall into CON_RETYPE_LOOP to emit
;              spaces until CON_COL reaches CON_LINE_START_COL.
;   [RE] Twin of the 44K CON_RETYPE_LINE (60K's CON_LINE_KILL auto-name).
; ----------------------------------------------------------------------
CON_RETYPE_LINE:
        LD C,$23
        CALL CON_PUT_COL
        CALL CON_CRLF
; ----------------------------------------------------------------------
; CON_RETYPE_LOOP -- advance the cursor with spaces until the column matches the start count.
;   In: CON_LINE_START_COL = target column; CON_COL = current column.
;   Out: spaces emitted until CON_COL >= CON_LINE_START_COL.  Clobbers: AF, C, HL.
;   Algorithm: while CON_COL < CON_LINE_START_COL, emit a space via CON_PUT_COL and loop.
;   [RE] Re-echo loop of CON_RETYPE_LINE (44K twin).
; ----------------------------------------------------------------------
CON_RETYPE_LOOP:
        LD A,(CON_COL)
        LD HL,CON_LINE_START_COL
        CP (HL)
        RET NC
        LD C,$20
        CALL CON_PUT_COL
        JR CON_RETYPE_LOOP
CON_CRLF:
        LD C,$0D
        CALL CON_PUT_COL
        LD C,$0A
        JR CON_PUT_COL
; [DOC CPMREF 3-44] Print String helper (BDOS fn 9 body): writes successive characters from the
;       buffer addressed by BC to the console until the '$' terminator ($24) is reached.
; ----------------------------------------------------------------------
; CON_PRINT_STR -- print a '$'-terminated string to the console.
;   In: BC = pointer to the string; terminated by '$' ($24).
;   Out: each char emitted via F_CONOUT_H until '$' is reached.  Clobbers: AF, BC, C.
;   Algorithm: load (BC); if '$' return; else advance BC, output the char via F_CONOUT_H
;              (preserving BC), and loop.
;   [DOC CPMREF 3-44] Backs BDOS function 9 (Print String) and the BDOS error banner. Twin of
;        the 44K CON_PRINT_STR.
; ----------------------------------------------------------------------
CON_PRINT_STR:
        LD A,(BC)
        CP $24                           ; '$' string terminator
        RET Z
        INC BC
        PUSH BC
        LD C,A
        CALL F_CONOUT_H
        POP BC
        JR CON_PRINT_STR
; [DOC CPMREF 3-44] Read Console Buffer (BDOS fn 10): edited line input into the buffer pointed
;       to by DE. The first buffer byte is the maximum count (mx) read here into C; the second
;       byte (nc) receives the resulting character count; the typed characters follow. Implements
;       the CP/M line editor (ctl-H/rubout backspace, ctl-X line-kill, ctl-R retype, ctl-E phys
;       EOL, ctl-P printer echo, ctl-C reboot), terminating on CR ($0D) or LF ($0A).
; ----------------------------------------------------------------------
; F_READCONBUF_H -- BDOS buffered console line input (function 10) with editing.
;   In: BDOS_PARAM_PTR -> the read buffer (byte0 = max length, byte1 = returned count, data...).
;   Out: the buffer filled with the edited line; byte1 set to the char count.
;   Clobbers: AF, BC, DE, HL.
;   Algorithm: seed the echoed-count (CON_LINE_START_COL) from CON_COL; read chars one at a time
;              (CON_GETC_OR_RAW, masked to 7 bits) and dispatch the editing controls: CR/LF
;              terminate; BS/DEL delete; Ctrl-E new line; Ctrl-P printer toggle; Ctrl-X erase
;              line; Ctrl-U abandon ('#'); Ctrl-R retype; other chars stored. Ends by writing the
;              count and a CR.
;   [DOC CPMREF 3-44] Classic CP/M 2.2 line editor (Read Console Buffer). Twin of 44K
;        F_READCONBUF_H; dispatch fn 10.
; ----------------------------------------------------------------------
F_READCONBUF_H:
        LD A,(CON_COL)
        LD (CON_LINE_START_COL),A
        LD HL,(BDOS_PARAM_PTR)
        LD C,(HL)                        ; 4E    mx = buffer max count (first byte)
        INC HL
        PUSH HL
        LD B,$00
; ----------------------------------------------------------------------
; READBUF_NEXT -- top of the line-editor read loop: save state and fetch a char.
;   In: B = count so far, HL -> buffer position.
;   Out: falls into READBUF_GETC with BC/HL preserved on the stack.  Clobbers: stack.
;   [RE] Per-keystroke loop head of F_READCONBUF_H (44K twin).
; ----------------------------------------------------------------------
READBUF_NEXT:
        PUSH BC
        PUSH HL
; ----------------------------------------------------------------------
; READBUF_GETC -- read and classify the next edit character.
;   In: stacked BC/HL = saved count and buffer pointer.
;   Out: A = 7-bit char; control codes dispatched to the appropriate editor handler.
;   Clobbers: AF, BC, HL.
;   Algorithm: CON_GETC_OR_RAW, mask to 7 bits, restore BC/HL, then chain CP/JP tests: CR/LF ->
;              READBUF_DONE; BS -> back up one char (READBUF_REDISPLAY path); else fall to the
;              DEL/control handlers.
;   [RE] Keystroke dispatcher inside F_READCONBUF_H (44K twin).
; ----------------------------------------------------------------------
READBUF_GETC:
        CALL CON_GETC_OR_RAW
        AND $7F
        POP HL
        POP BC
        CP $0D
        JP Z,READBUF_DONE
        CP $0A
        JP Z,READBUF_DONE
        CP $08
        JR NZ,READBUF_DEL
        LD A,B
        OR A
        JR Z,READBUF_NEXT
        DEC B
        LD A,(CON_COL)
        LD (CON_SAVED_COL),A
        JR READBUF_REDISPLAY
; ----------------------------------------------------------------------
; READBUF_DEL -- handle DEL ($7F) as a destructive rubout of the previous char.
;   In: A = char, B = count, HL -> buffer position.
;   Out: if buffer nonempty, last char fetched for re-echo and pointer/count backed up; empty
;        buffer just re-loops.  Clobbers: AF, B, HL.
;   [RE] DELETE-key path of the line editor (44K twin).
; ----------------------------------------------------------------------
READBUF_DEL:
        CP $7F
        JR NZ,READBUF_CTRL_E
        LD A,B
        OR A
        JR Z,READBUF_NEXT
        LD A,(HL)
        DEC B
        DEC HL
        JR READBUF_STORE_ECHO
; ----------------------------------------------------------------------
; READBUF_CTRL_E -- handle Ctrl-E ($05): physical CR/LF without ending the line.
;   In: A = char, BC/HL = editor state.  Out: cursor moved to a new line, echoed-count reset;
;       editing continues.  Clobbers: AF.
;   Algorithm: on Ctrl-E print CR/LF (CON_CRLF), zero CON_LINE_START_COL, resume at READBUF_GETC;
;              otherwise fall through to READBUF_CTRL_P.
;   [RE] 44K twin.
; ----------------------------------------------------------------------
READBUF_CTRL_E:
        CP $05
        JR NZ,READBUF_CTRL_P
        PUSH BC
        PUSH HL
        CALL CON_CRLF
        XOR A
        LD (CON_LINE_START_COL),A
        JR READBUF_GETC
; ----------------------------------------------------------------------
; READBUF_CTRL_P -- handle Ctrl-P ($10): toggle the printer (list-device) echo flag.
;   In: A = char.  Out: CON_LIST_ECHO flipped between 0 and 1; editing continues.
;   Clobbers: AF, HL.
;   Algorithm: on Ctrl-P compute 1 - CON_LIST_ECHO to toggle, then loop (READBUF_NEXT);
;              otherwise fall through to READBUF_CTRL_X.
;   [RE] 44K twin.
; ----------------------------------------------------------------------
READBUF_CTRL_P:
        CP $10
        JR NZ,READBUF_CTRL_X
        PUSH HL
        LD HL,CON_LIST_ECHO
        LD A,$01
        SUB (HL)
        LD (HL),A
        POP HL
        JR READBUF_NEXT
; ----------------------------------------------------------------------
; READBUF_CTRL_X -- handle Ctrl-X ($18): erase the whole input line.
;   In: A = char; CON_COL = column; CON_LINE_START_COL = start column.
;   Out: all echoed chars backspaced away and the buffer emptied; editing restarts.
;   Clobbers: AF, HL.
;   Algorithm: on Ctrl-X drop the buffer pointer and fall into READBUF_ERASE_LOOP; else fall to
;              READBUF_CTRL_U.
;   [RE] 44K twin.
; ----------------------------------------------------------------------
READBUF_CTRL_X:
        CP $18
        JR NZ,READBUF_CTRL_U
        POP HL
; ----------------------------------------------------------------------
; READBUF_ERASE_LOOP -- backspace-erase characters back to the line start.
;   In: CON_LINE_START_COL = start column, CON_COL = current column.
;   Out: console column reduced to the start; chars visually erased; restarts F_READCONBUF_H.
;   Clobbers: AF, HL.
;   Algorithm: while CON_COL > CON_LINE_START_COL, decrement it and CON_BACKSPACE; then restart
;              the read with an empty buffer.
;   [RE] 44K twin.
; ----------------------------------------------------------------------
READBUF_ERASE_LOOP:
        LD A,(CON_LINE_START_COL)
        LD HL,CON_COL
        CP (HL)
        JR NC,F_READCONBUF_H
        DEC (HL)
        CALL CON_BACKSPACE
        JR READBUF_ERASE_LOOP
; ----------------------------------------------------------------------
; READBUF_CTRL_U -- handle Ctrl-U ($15): abandon the line, show '#', restart.
;   In: A = char.  Out: '#' printed, fresh line started, buffer reset (restarts F_READCONBUF_H).
;   Clobbers: AF, HL.
;   Algorithm: on Ctrl-U call CON_RETYPE_LINE ('#'+CRLF) and restart the read; otherwise fall to
;              READBUF_CTRL_R.
;   [RE] 44K twin.
; ----------------------------------------------------------------------
READBUF_CTRL_U:
        CP $15
        JR NZ,READBUF_CTRL_R
        CALL CON_RETYPE_LINE
        POP HL
        JR F_READCONBUF_H
; ----------------------------------------------------------------------
; READBUF_CTRL_R -- handle Ctrl-R ($12): retype the current line, else store the char.
;   In: A = char, B = count, HL -> buffer.
;   Out: Ctrl-R reprints the buffer (falls into READBUF_REDISPLAY); any other char jumps to the
;        store path (READBUF_STORE).  Clobbers: AF.
;   [RE] 44K twin.
; ----------------------------------------------------------------------
READBUF_CTRL_R:
        CP $12
        JR NZ,READBUF_STORE
; ----------------------------------------------------------------------
; READBUF_REDISPLAY -- reprint the buffered line after a retype/delete.
;   In: B = char count; buffer pointer on stack (HL).
;   Out: '#'/CRLF emitted then each buffered char re-echoed via CON_PUT_VISIBLE.
;   Clobbers: AF, BC, HL.
;   Algorithm: CON_RETYPE_LINE for the marker, then walk the buffer (READBUF_REDISPLAY_LOOP)
;              re-echoing each stored char with CON_PUT_VISIBLE (controls show as '^X').
;   [RE] Used by Ctrl-R and after a backspace. 44K twin.
; ----------------------------------------------------------------------
READBUF_REDISPLAY:
        PUSH BC
        CALL CON_RETYPE_LINE
        POP BC
        POP HL
        PUSH HL
        PUSH BC
; ----------------------------------------------------------------------
; READBUF_REDISPLAY_LOOP -- re-echo each buffered character.
;   In: B = remaining count, HL -> buffer position.
;   Out: every buffered char emitted via CON_PUT_VISIBLE.  Clobbers: AF, BC, C, HL.
;   Algorithm: while B != 0, advance HL, load the char, CON_PUT_VISIBLE it, decrement B; on
;              exhaustion fall into READBUF_REPOS.
;   [RE] 44K twin.
; ----------------------------------------------------------------------
READBUF_REDISPLAY_LOOP:
        LD A,B
        OR A
        JR Z,READBUF_REPOS
        INC HL
        LD C,(HL)
        DEC B
        PUSH BC
        PUSH HL
        CALL CON_PUT_VISIBLE
        POP HL
        POP BC
        JR READBUF_REDISPLAY_LOOP
; ----------------------------------------------------------------------
; READBUF_REPOS -- after redisplay, backspace the cursor to the edit position.
;   In: CON_SAVED_COL = saved column to restore to, CON_COL = current column.
;   Out: cursor moved back so further typing continues at the right spot.  Clobbers: AF, HL.
;   Algorithm: if no saved position (CON_SAVED_COL==0) resume at READBUF_GETC; else compute how
;              far past the target the cursor is (CON_SAVED_COL := saved - column) and fall into
;              READBUF_REPOS_LOOP.
;   [RE] Cursor-reposition step after a Ctrl-R / delete redisplay. 44K twin.
; ----------------------------------------------------------------------
READBUF_REPOS:
        PUSH HL
        LD A,(CON_SAVED_COL)
        OR A
        JP Z,READBUF_GETC
        LD HL,CON_COL
        SUB (HL)
        LD (CON_SAVED_COL),A
; ----------------------------------------------------------------------
; READBUF_REPOS_LOOP -- backspace the cursor by the computed cell count.
;   In: CON_SAVED_COL = number of cells to back up.
;   Out: cursor repositioned; loop ends and the editor reads the next char (READBUF_GETC).
;   Clobbers: AF, HL.
;   Algorithm: CON_BACKSPACE, decrement CON_SAVED_COL, repeat until zero, then resume input.
;   [RE] 44K twin.
; ----------------------------------------------------------------------
READBUF_REPOS_LOOP:
        CALL CON_BACKSPACE
        LD HL,CON_SAVED_COL
        DEC (HL)
        JR NZ,READBUF_REPOS_LOOP
        JP READBUF_GETC
; ----------------------------------------------------------------------
; READBUF_STORE -- store an ordinary character into the input buffer.
;   In: A = char to store, B = count, HL -> next buffer slot.
;   Out: char written, count incremented; falls into READBUF_STORE_ECHO.  Clobbers: AF, B, HL.
;   Algorithm: write the char at ++HL, bump B, then fall into the echo/limit check.
;   [RE] Line editor's character-store path. 44K twin.
; ----------------------------------------------------------------------
READBUF_STORE:
        INC HL
        LD (HL),A
        INC B
; ----------------------------------------------------------------------
; READBUF_STORE_ECHO -- echo the stored char and enforce the buffer length limit.
;   In: A = char, B = count, C = buffer max length.
;   Out: char echoed; if count reached the max (or a degenerate max) the line terminates,
;        otherwise reading continues.  Clobbers: AF, BC, HL.
;   Algorithm: echo via CON_PUT_VISIBLE; reload the buffer max; if the max byte is 1 (degenerate)
;              warm-boot (JP 0); if count == max terminate (READBUF_LIMIT), else loop.
;   [RE] 44K twin. [?] exact degenerate-max semantics beyond 'terminate when full' UNKNOWN.
; ----------------------------------------------------------------------
READBUF_STORE_ECHO:
        PUSH BC
        PUSH HL
        LD C,A
        CALL CON_PUT_VISIBLE
        POP HL
        POP BC
        LD A,(HL)
        CP $03
        LD A,B
        JR NZ,READBUF_LIMIT
        CP $01
        JP Z,WBOOTV
; ----------------------------------------------------------------------
; READBUF_LIMIT -- compare the count to the buffer max and continue or finish.
;   In: A = count (B), C = buffer maximum length.
;   Out: if count < max keep reading (READBUF_NEXT), else fall into READBUF_DONE.
;   Clobbers: AF.
;   Algorithm: CP C; if count < max (carry) loop, else finish. [RE] 44K twin.
; ----------------------------------------------------------------------
READBUF_LIMIT:
        CP C
        JP C,READBUF_NEXT
; ----------------------------------------------------------------------
; READBUF_DONE -- finish the input line: store the count and emit a CR.
;   In: stacked HL -> buffer count byte; B = final character count.
;   Out: count written into the buffer; CR echoed; returns to the BDOS caller.
;   Clobbers: AF, C, HL.
;   Algorithm: pop the buffer pointer, store B as the returned count, then tail-call CON_PUT_COL
;              with CR ($0D) to close the input line.
;   [RE] Reached on CR/LF/buffer-full. 44K twin.
; ----------------------------------------------------------------------
READBUF_DONE:
        POP HL
        LD (HL),B
        LD C,$0D
        JP CON_PUT_COL
; [DOC CPMREF 3-44] Console Input (BDOS fn 1): reads one character from the console (with echo,
;       tab expansion, and ctl-S/ctl-P handling) and returns it in A.
; ----------------------------------------------------------------------
; F_CONIN_H -- BDOS function 1 handler: console input with echo, returned in A.
;   In: none.  Out: BDOS result (BDOS_RETVAL) = char read.  Clobbers: AF, BC, HL.
;   Algorithm: read+echo via F_CONIN_RAW, then store the char through BDOS_RET_RESULT.
;   [DOC CPMREF 3-44] Dispatch-table entry for function 1. Twin of 44K F_CONIN_H.
; ----------------------------------------------------------------------
F_CONIN_H:
        CALL F_CONIN_RAW
        JR BDOS_RET_RESULT
; [DOC CPMREF 3-44] Reader Input (BDOS fn 3): returns one character from the logical RDR: device
;       (BIOS READER entry) in A.
; ----------------------------------------------------------------------
; F_READERIN_H -- BDOS function 3 handler: read from the reader (RDR/AUX) device.
;   In: none.  Out: BDOS result (BDOS_RETVAL) = byte from the BIOS READER vector.  Clobbers: AF.
;   Algorithm: call the BIOS reader-input vector (READER $FA15), store the byte via
;              BDOS_RET_RESULT.
;   [DOC CPMREF 3-44] Dispatch entry for function 3 (Reader Input). Twin of 44K F_READERIN_H.
; ----------------------------------------------------------------------
F_READERIN_H:
        CALL READER
        JR BDOS_RET_RESULT
; [DOC CPMREF 3-44] Direct Console I/O (BDOS fn 6): if E=$FF (here C=$FF, INC->$00) it returns an
;       input char or $00-status; otherwise E is a character sent raw to the console (no ctl-S/ctl-P
;       processing). The E=$FE status form is a CP/M extension; this build handles it via the second
;       INC (C=$FE).
; ----------------------------------------------------------------------
; F_DIRECTIO_H -- BDOS function 6 handler: direct console I/O.
;   In: C = subfunction ($FF = input/status, $FE = status only, else = output char).
;   Out: input/status results via BDOS_RET_RESULT; output sent raw to the console.  Clobbers: AF.
;   Algorithm: C==$FF (INC A -> Z) -> DIRECTIO_INPUT; C==$FE (second INC A -> Z) -> raw BIOS
;              CONST ($FA06); otherwise send C to BIOS CONOUT ($FA0C), bypassing editor and flow
;              control.
;   [DOC CPMREF 3-44] Dispatch entry for function 6 (Direct Console I/O). Twin of 44K
;        F_DIRECTIO_H.
; ----------------------------------------------------------------------
F_DIRECTIO_H:
        LD A,C
        INC A                            ; 3C    C=$FF (input request) -> Z
        JR Z,DIRECTIO_INPUT
        INC A                            ; 3C    C=$FE (status request) -> Z
        JP Z,CONST
        JP CONOUT                        ; otherwise output the raw character
; ----------------------------------------------------------------------
; DIRECTIO_INPUT -- direct console input subfunction of function 6.
;   In: none.  Out: BDOS result = char if one is ready, else 0; no echo, no flow control.
;   Clobbers: AF.
;   Algorithm: poll raw BIOS CONST ($FA06); if no key, return 0 via BDOS_EXIT_RESTORE; if a key
;              is ready read it raw (CONIN $FA09) and store via BDOS_RET_RESULT.
;   [RE] 44K twin (DIRECTIO_INPUT); this is direct console input, not an FCB/directory routine.
; ----------------------------------------------------------------------
DIRECTIO_INPUT:
        CALL CONST
        OR A
        JP Z,BDOS_EXIT_RESTORE           ; no char ready -> return $00
        CALL CONIN
        JR BDOS_RET_RESULT
; [DOC CPMREF 3-50] Get I/O Byte (BDOS fn 7): returns the current IOBYTE_ADDR ($0003) in A.
; ----------------------------------------------------------------------
; F_GETIOB_H -- BDOS function 7 handler: get the I/O byte (IOBYTE_ADDR).
;   In: none.  Out: BDOS result = the IOBYTE_ADDR at fixed address $0003.  Clobbers: AF.
;   Algorithm: load (IOBYTE_ADDR) and return it via BDOS_RET_RESULT.
;   [DOC CPMREF 3-50] Dispatch entry for function 7. Twin of 44K F_GETIOB_H.
; ----------------------------------------------------------------------
F_GETIOB_H:
        LD A,(IOBYTE_ADDR)
        JR BDOS_RET_RESULT
; [DOC CPMREF 3-51] Set I/O Byte (BDOS fn 8): stores E (passed in C here) into the IOBYTE_ADDR ($0003).
; ----------------------------------------------------------------------
; F_SETIOB_H -- BDOS function 8 handler: set the I/O byte (IOBYTE_ADDR).
;   In: C = new IOBYTE_ADDR value.  Out: (IOBYTE_ADDR) = C.  Clobbers: HL.
;   Algorithm: store C into the fixed IOBYTE_ADDR cell at $0003 and return.
;   [DOC CPMREF 3-51] Dispatch entry for function 8. Twin of 44K F_SETIOB_H.
; ----------------------------------------------------------------------
F_SETIOB_H:
        LD HL,IOBYTE_ADDR
        LD (HL),C
        RET
; [DOC CPMREF 3-44] Print String (BDOS fn 9): DE addresses a '$'-terminated string; move it into BC
;       and fall into the CON_PRINT_STR helper to emit it to the console.
; ----------------------------------------------------------------------
; F_PRINTSTR_H -- BDOS function 9 handler: print a '$'-terminated string.
;   In: DE = pointer to the string.  Out: string echoed up to the '$'.  Clobbers: AF, BC.
;   Algorithm: move DE into BC and tail-call CON_PRINT_STR.
;   [DOC CPMREF 3-44] Dispatch entry for function 9. Twin of 44K F_PRINTSTR_H.
; ----------------------------------------------------------------------
F_PRINTSTR_H:
        EX DE,HL
        LD C,L
        LD B,H
        JP CON_PRINT_STR
; [DOC CPMREF 3-44] Get Console Status (BDOS fn 11): returns A=$FF if a console character is ready,
;       $00 otherwise (also services the ctl-S pause / ctl-C warm-boot break check).
; ----------------------------------------------------------------------
; F_CONSTAT_H -- BDOS function 11 handler: get console status.
;   In: none.  Out: BDOS result = 1 if a console char is ready, else 0.  Clobbers: AF.
;   Algorithm: CON_POLL_STATUS to test readiness (handling Ctrl-S/Ctrl-C), then fall into
;              BDOS_RET_RESULT to store the 0/1 status.
;   [DOC CPMREF 3-44] Dispatch entry for function 11. Twin of 44K F_CONSTAT_H.
; ----------------------------------------------------------------------
F_CONSTAT_H:
        CALL CON_POLL_STATUS
; Stores the byte result in A into the BDOS return-value cell (read back into A=L,B=H on BDOS exit).
; ----------------------------------------------------------------------
; BDOS_RET_RESULT -- store A as the BDOS function return value and return.
;   In: A = result byte.  Out: BDOS_RETVAL (low byte) = A.  Clobbers: none beyond the cell.
;   Algorithm: write A to BDOS_RETVAL; the handler then RETs through the pushed bank-out epilogue
;              (BDOS_BANK_OUT_EPILOG). Common tail of the console handlers.
;   [RE] The BDOS result sink read back on exit (A=L, B=H). Twin of 44K BDOS_RET_RESULT.
; ----------------------------------------------------------------------
BDOS_RET_RESULT:
        LD (BDOS_RETVAL),A
; ----------------------------------------------------------------------
; BDOS_RET_NOP -- bare RET; the dispatch-table target for the no-op functions 38 and 39.
;   In/Out: none.  Clobbers: none.
;   [RE] SoftCard extension slots 38/39 do nothing (matches the 44K $9F04 RET). The following
;        DEFB $3E,$01,$18,$F8 is the unlabeled 'A:=1; JR BDOS_RET_RESULT' fragment (BDOS_RET_ONE
;        in the 44K twin), reached only by fall-through/JR, not by name here.
; ----------------------------------------------------------------------
BDOS_RET_NOP:
        RET
        DEFB    $3E,$01,$18,$F8
; ----------------------------------------------------------------------
; CON_SAVED_COL -- saved cursor column for line-editor redisplay/reposition; also a
;   'suppress status-poll/echo' flag inside CON_PUT_COL (nonzero => skip poll+echo).
;   [RE] BDOS console state byte; zero when not repositioning. Twin of 44K CON_SAVED_COL
;        (60K auto-named CON_CRLF_30).
; ----------------------------------------------------------------------
CON_SAVED_COL:
        DEFB    $00
; ----------------------------------------------------------------------
; CON_LINE_START_COL -- column at the start of the current input line (echoed-count base).
;   [RE] Used by the line editor to know how far back Ctrl-X / DEL may erase. Twin of 44K
;        CON_LINE_START_COL.
; ----------------------------------------------------------------------
CON_LINE_START_COL:
        DEFB    $00
; ----------------------------------------------------------------------
; CON_COL -- current console output column counter.
;   [RE] Incremented per printable char, reset by LF; drives tab expansion and editing. Twin of
;        44K CON_COL.
; ----------------------------------------------------------------------
CON_COL:
        DEFB    $00
; ----------------------------------------------------------------------
; CON_LIST_ECHO -- printer (list device) echo flag; nonzero => mirror console output to LIST.
;   [RE] Toggled by the line editor's Ctrl-P (READBUF_CTRL_P). Twin of 44K CON_LIST_ECHO.
; ----------------------------------------------------------------------
CON_LIST_ECHO:
        DEFB    $00
; ----------------------------------------------------------------------
; CON_PENDING_CHAR -- 1-byte console type-ahead / un-get buffer (0 = empty).
;   [RE] Filled by CON_POLL_STATUS, consumed by CON_GETC_OR_RAW. Twin of 44K CON_PENDING_CHAR.
; ----------------------------------------------------------------------
CON_PENDING_CHAR:
        DEFB    $00
BDOS_SAVED_SP:
        DEFS    50, $00                  ; fill
; ----------------------------------------------------------------------
; BDOS_STACK_TOP -- top of the BDOS private stack (SP loaded here on entry).
;   [RE] BDOS_ENTRY does LD SP,BDOS_STACK_TOP before dispatching; the preceding DEFS reserves the
;        stack slack below it. Twin of 44K BDOS_STACK_TOP (60K auto-named BDOS_STACK).
; ----------------------------------------------------------------------
BDOS_STACK_TOP:
        DEFB    $00
; ----------------------------------------------------------------------
; BDOS_CUR_DRIVE -- the drive the BDOS is currently operating on (0=A..15=P).
;   [RE] Set by the drive-select path and read all over the file system. Twin of the 44K
;        BDOS_CUR_DRIVE at $9F42; this is that cell relocated by the upper-bank +$3FCE.
; ----------------------------------------------------------------------
BDOS_CUR_DRIVE:
        DEFB    $00
; ----------------------------------------------------------------------
; BDOS_PARAM_PTR -- saved DE parameter pointer from the BDOS call (FCB / DMA / buffer). 16-bit.
;   [RE] BDOS_ENTRY stashes the incoming DE here; consumers reload it as the operand pointer
;        (e.g. the dispatcher and F_READCONBUF_H). Twin of 44K BDOS_PARAM_PTR.
; ----------------------------------------------------------------------
BDOS_PARAM_PTR:
        DEFB    $00,$00
; ----------------------------------------------------------------------
; BDOS_RETVAL -- BDOS function return value (16-bit: low byte = A result, high = B).
;   [RE] Pre-seeded to 0 on entry; written by BDOS_RET_RESULT; loaded back into HL (A=L, B=H) by
;        BDOS_LOAD_RESULT on exit. Twin of 44K BDOS_RETVAL. The bytes after the 2-byte cell begin
;        the $DF15 error-vector jump helper (LD HL,$DC0B / LD E,(HL)/INC HL/LD D,(HL)/EX DE,HL/
;        bank2 / JP (HL)) that dispatches the BDOS_ERROR reporter addresses at $DC09/$DC0B.
; ----------------------------------------------------------------------
BDOS_RETVAL:
        DEFB    $00,$00,$21,$0B,$DC,$5E,$23,$56,$EB,$32
        DEFW    LC_BANK2
        DEFB    $E9,$32
        DEFW    LC_BANK2
        DEFB    $CD,$27,$FA,$18,$06,$32
        DEFW    LC_BANK2
        DEFB    $CD,$2A,$FA,$B7,$28,$10,$21,$09,$DC,$18,$E2
; ----------------------------------------------------------------------
; LC_BANK1_CALL_ISCTRL -- bank the lower LC in and call IS_CTRL_CHAR ($B5C0).
;   In: A = character to classify.  Out: per IS_CTRL_CHAR -- carry set if A is a control char the
;        line editor must expand (A < ' ' and not CR/LF/TAB/BS); the lower-bank tail restores
;        bank2 and returns.  Clobbers: AF, flags.
;   Algorithm: LD (LC_BANK1),A selects LC bank1 (Apple $C08B) so the classifier at $B5C0 is
;              visible, then JP IS_CTRL_CHAR (IS_CTRL_CHAR); that routine ends with JP LC_BANK2_RET to
;              bank2 back in and RET to the upper-bank caller.
;   [RE] 60K bank-switch trampoline (no 44K counterpart -- 44K calls IS_CTRL_CHAR directly).
; ----------------------------------------------------------------------
LC_BANK1_CALL_ISCTRL:
        LD (LC_BANK1),A
        JP IS_CTRL_CHAR
        DEFB    $32
        DEFW    LC_BANK2
        DEFB    $ED,$B0,$32
        DEFW    LC_BANK1
        DEFB    $C9
BDOS_BANK_OUT_EPILOG:
        DEFB    $32
        DEFW    LC_BANK1
        DEFB    $3A,$EB,$BF,$B7,$28,$15,$2A
        DEFW    BDOS_PARAM_PTR
        DEFB    $36,$00,$3A,$ED,$BF,$B7,$28,$0A,$77,$3A,$EC,$BF,$32,$E3,$BF,$CD
        DEFB    $47,$BE
BDOS_EXIT_RESTORE:
        LD (LC_BANK2),A
        LD A,(DEFERRED_COPY_FLAG)
        OR A
        JR Z,BDOS_LOAD_RESULT
        LD DE,(DEFERRED_COPY_DST)
        LD HL,DEFERRED_COPY_BUF
        LD BC,$0024
        LDIR
; [DOC CPMREF 3-44] BDOS return: load the result word into HL, then set A=L and B=H so callers see
;       byte results in A and word results in HL per the standard CP/M return convention.
; ----------------------------------------------------------------------
; BDOS_LOAD_RESULT -- load the BDOS result and restore the caller's stack on exit.
;   In: BDOS_RETVAL = result word; BDOS_SAVED_SP = caller SP.
;   Out: HL = result, A = L (byte result), B = H (word high); SP restored; falls into
;        LC_BANK2_RET to bank2 back in and RET to the $0005 caller.  Clobbers: AF, BC, HL, SP.
;   Algorithm: LD HL,(BDOS_RETVAL); LD A,L; LD B,H; LD SP,(BDOS_SAVED_SP); fall into LC_BANK2_RET.
;   [DOC CPMREF 3-44] Standard CP/M return convention (A=L, HL=word). Reached from
;        BDOS_EXIT_RESTORE after the optional deferred copy-back. 60K-specific epilogue tail.
; ----------------------------------------------------------------------
BDOS_LOAD_RESULT:
        LD HL,(BDOS_RETVAL)
        LD A,L                           ; 7D    A = L (byte result)
        LD B,H                           ; 44    B = H (high half of word result)
        LD SP,(BDOS_SAVED_SP)            ; restore caller's stack pointer
LC_BANK2_RET:
        LD (LC_BANK2),A
        RET
; ----------------------------------------------------------------------
; DEFERRED_COPY_DST -- 16-bit destination pointer for the pending exit copy-back. DATA.
;   [RE] When DEFERRED_COPY_FLAG is set, BDOS_EXIT_RESTORE LDIRs $24 (36) bytes from
;        DEFERRED_COPY_BUF to the address held here, then clears the flag. Believed to be the
;        saved search-FCB write-back target the manual notes for Search-First/Next. [?] exact
;        producer UNKNOWN (set by a lower-bank $Bxxx handler). 60K-specific cell.
; ----------------------------------------------------------------------
DEFERRED_COPY_DST:
        DEFB    $00,$00
; ----------------------------------------------------------------------
; DEFERRED_COPY_FLAG -- 1-byte 'copy-back pending' flag for the BDOS exit path. DATA.
;   [RE] Cleared on entry (BDOS_ENTRY, $DC30); if nonzero at exit, BDOS_EXIT_RESTORE performs the
;        deferred 36-byte LDIR (DEFERRED_COPY_BUF -> DEFERRED_COPY_DST). Set by a lower-bank
;        handler. 60K-specific cell. [?] exact producer UNKNOWN.
; ----------------------------------------------------------------------
DEFERRED_COPY_FLAG:
        DEFB    $00
; ----------------------------------------------------------------------
; DEFERRED_COPY_BUF -- 36-byte staging buffer (LDIR source) for the deferred exit copy-back. DATA.
;   [RE] BDOS_EXIT_RESTORE copies these $24 bytes to DEFERRED_COPY_DST when DEFERRED_COPY_FLAG is
;        set. Sized 36 = a 32-byte directory FCB image plus a few control bytes. The 6502 bytes
;        that follow at $DFAC-$DFEB are an out-of-band payload past this cell, not part of it.
;        60K-specific buffer. [?] exact contents/producer UNKNOWN.
; ----------------------------------------------------------------------
DEFERRED_COPY_BUF:
        DEFS    36, $00                  ; fill
        DEFB    $8D,$83,$C0,$A2,$AC,$2C,$A2,$AA,$88,$B1,$3E,$4A,$3E,$56,$0B,$4A
        DEFB    $3E,$56,$0B,$99,$00,$09,$E8,$D0,$EF,$98,$D0,$EA,$4C,$E5,$FF,$8D
        DEFB    $83,$C0,$A0,$00,$A2,$56,$CA,$30,$FB,$B9,$00,$09,$5E,$00,$0C,$2A
        DEFB    $5E,$00,$0C,$2A,$91,$3E,$C8,$D0,$ED,$8D,$8B,$C0,$60,$00,$00,$00
        DEFS    20, $00                  ; fill
; ===========================================================================
; LOWER LC BANK -- the FCB/file/directory/disk machinery (run $B5C0-$BFBF).
; Stored contiguously in the BDOS image at $E000-$E9FF but RUN in the Language
; Card low mirror (Apple $D5C0-$DFFF, bank 1): the cold-boot relocator copies
; these pages down there, so the CPU executes them at $B5C0-$BFBF (= storage
; -$2A40). DISP makes every in-image label resolve to its true $Bxxx run address
; while the bytes are emitted at their $E0xx image position. The dispatcher at
; $DC11 banks this half in (LC_BANK1) before an indexed JP (HL) reaches a handler
; here; the $BFC0-$BFFF scratch these routines use is live RAM, past the image.
; sjasmplus can't nest DISP, so close the upper-bank $DC00 DISP first (linked
; build only; the standalone build reached here under a plain ORG $DC00).
; ===========================================================================
    IFDEF CPM60_LINK
    ENT                ; close the upper-bank DISP $DC00 (linked build)
    ENDIF
    DISP $B5C0
; ----------------------------------------------------------------------
; IS_CTRL_CHAR -- classify A as a printable/control character for the console echo path.
;   In: A = character to test.
;   Out: carry set when A is a control character that the line editor must expand (below space and
;        not one of CR/LF/TAB/BS); carry clear for CR/LF/TAB/BS and for printable chars (>= space).
;   Clobbers: A,flags (the tail-JP LC_BANK2_RET = upper-bank LC_BANK2_RET banks bank2 back in and returns).
;   Algorithm: compare A against CR($0D)/LF($0A)/TAB($09)/BS($08) (each a non-control 'pass'), then
;       CP $20; JP LC_BANK2_RET leaves carry = (A < $20) for the remaining control chars. Lives in the lower
;       LC bank; the upper-bank echo caller reaches it via LC_BANK1_CALL_ISCTRL ($DF36).
;   [RE] control-char discriminator for CON_PUT_VISIBLE (^X caret display). [?]
; ----------------------------------------------------------------------
IS_CTRL_CHAR:
        CP $0D
        JR Z,IS_CTRL_CHAR_TAIL
        CP $0A
        JR Z,IS_CTRL_CHAR_TAIL
        CP $09
        JR Z,IS_CTRL_CHAR_TAIL
        CP $08
        JR Z,IS_CTRL_CHAR_TAIL
        CP $20
IS_CTRL_CHAR_TAIL:
        JP LC_BANK2_RET
; ----------------------------------------------------------------------
; CON_TRACK_COL -- update the console column counter (CON_COL=$DEDA) for one output char.
;   In: C = character being emitted.
;   Out: the column cell $DEDA advanced for a printable char, decremented for a backspace, and left
;        unchanged for rubout ($7F) or when already at column 0.  Clobbers: A,HL,flags.
;   Algorithm: HL := $DEDA (upper-bank CON_COL); RET on rubout; INC the column, but if the char is
;       a control code (< space) undo it, and for BS ($08) tail to $DD64 (the upper-bank column-fix
;       stub) to also DEC. Runs in the lower LC bank; called from LC_BANK1_CALL_TRACKCOL via CALL CON_TRACK_COL.
;   [RE] column tracker feeding TAB expansion and line-edit backspace. [?]
; ----------------------------------------------------------------------
CON_TRACK_COL:
        LD A,C
        LD HL,CON_COL
        CP $7F
        RET Z
        INC (HL)
        CP $20
        RET NC
        DEC (HL)
        LD A,(HL)
        OR A
        RET Z
        LD A,C
        CP $08
        JP NZ,$DD64
        DEC (HL)
        RET
; ----------------------------------------------------------------------
; SELDSK_DPB_FETCH -- SELDSK the current drive and cache its Disk Parameter Block fields locally.
;   In: current drive at $DF10 (BDOS upper-bank current-drive cell).
;   Out: Z (A=0) if the BIOS returned a null DPH (drive not present); else A=$FF and the DPB fields
;        are unpacked into the $BFxx work cells (translate ptr $BFC0, block-shift/mask/EXM into
;        $BFC2..$BFC6, the DPB word block $BFC6.. copied from the DPB, ALLOC-vec ptr region, etc.).
;   Clobbers: A,BC,DE,HL,flags.
;   Algorithm: A := (current drive $DF10); C := A; CALL BIOS SELDSK ($FA1B) -> HL = DPH; return Z if
;       HL is 0; walk the DPH to the DPB, stash the XLT/DPB pointers into the $BFC0-$BFC6 work cells,
;       LDIR the 8-byte DPB header and the 15-byte second block into $BFC6/$BFCE, set the block-width
;       flag $BFEA from DSM's high byte, and return A=$FF.
;   [RE] 60K equivalent of the 44K SELDSK/DPB-unpack; the DPB scratch lives in the LC low page ($BFxx
;        here, vs the 44K $A9xx). [?] exact cell roles cross-checked against the 44K twin.
; ----------------------------------------------------------------------
SELDSK_DPB_FETCH:
        LD A,(BDOS_CUR_DRIVE)
        LD C,A
        CALL SELDSK
        LD A,H
        OR L
        RET Z
        LD E,(HL)
        INC HL
        LD D,(HL)
        INC HL
        LD (DPB_WORK_PTR0),HL
        INC HL
        INC HL
        LD (DEBLOCK_HSTREC_PTR0),HL
        INC HL
        INC HL
        LD (DEBLOCK_HSTREC_PTR1),HL
        INC HL
        INC HL
        LD (DPB_XLT_PTR),DE
        LD DE,DIRBUF_PTR
        LD BC,$0008
        LDIR
        LD HL,(DPB_PTR)
        LD DE,DPB_SPT
        LD BC,$000F
        LDIR
        LD HL,(MAX_BLOCK_DSM)
        LD A,H
        LD HL,BLOCK_WIDTH_FLAG
        LD (HL),$FF
        OR A
        JR Z,SELDSK_DPB_FETCH_1
        LD (HL),$00
SELDSK_DPB_FETCH_1:
        LD A,$FF
        OR A
        RET
; ----------------------------------------------------------------------
; DISK_HOME_CLEAR_SCAN -- HOME the drive and reset the directory-scan record/position work cells.
;   In: DPB scratch pointers at $BFC2 (record-count work word ptr) and $BFC4 (scan-position word ptr).
;   Out: the BIOS head is homed and the two 16-bit work cells addressed by (DEBLOCK_HSTREC_PTR0) and (DEBLOCK_HSTREC_PTR1) are
;        zeroed, restarting a directory sweep from record 0.  Clobbers: A,HL,flags.
;   Algorithm: CALL BIOS HOME ($FA18); A := 0; zero the word at (DEBLOCK_HSTREC_PTR0) and the word at (DEBLOCK_HSTREC_PTR1).
;   [RE] scan-reset run at the start of ALLOC_VECTOR_BUILD and each DIR_SEARCH_FIRST. [?]
; ----------------------------------------------------------------------
DISK_HOME_CLEAR_SCAN:
        CALL HOME
        XOR A
        LD HL,(DEBLOCK_HSTREC_PTR0)
        LD (HL),A
        INC HL
        LD (HL),A
        LD HL,(DEBLOCK_HSTREC_PTR1)
        LD (HL),A
        INC HL
        LD (HL),A
        RET
; ----------------------------------------------------------------------
; REC_DIV4_SETUP -- derive the 128-byte disk record (CUR_RECORD >> 2) that holds the current dir entry.
;   In: CUR_RECORD = 16-bit current directory-entry index at $BFF7.
;   Out: the record number CUR_RECORD/4 stored into the two deblock work words $BFF2 and $BFF9.
;   Clobbers: A,BC,HL,flags.
;   Algorithm: HL := (CUR_RECORD $BFF7); C := 2; SHR_HL_C (>>2 = four 32-byte entries per 128-byte
;       record); store HL to $BFF2 and $BFF9; fall into RECORD_TO_TRACK.
;   [RE] CP/M packs four 32-byte directory entries per 128-byte record; this picks the record. [?]
; ----------------------------------------------------------------------
REC_DIV4_SETUP:
        LD HL,(CUR_RECORD)
        LD C,$02
        CALL SHR_HL_C
        LD (CUR_BLOCK_NUMBER),HL
        LD (REC_CACHE),HL
; ----------------------------------------------------------------------
; RECORD_TO_TRACK -- translate the target logical record into a physical track/sector and program the BIOS.
;   In: the record word at $BFF2; DPB fields cached in the $BFxx work cells (sectors-per-track word
;       (DPB_SPT), track-offset (DPB_XLT_PTR), skew-table (DPB_OFF)).
;   Out: BIOS SETTRK/SETSEC set for the record via the BIOS SECTRAN/step vectors; track/sector work
;        cells ($BFC2/$BFC4) updated.  Clobbers: A,BC,DE,HL,flags.
;   Algorithm: subtract whole tracks (sectors-per-track) from the record to get track# and
;       sector-within-track, add the DPB track offset, program the BIOS via the $FAxx SET* vectors,
;       and SECTRAN the sector through the skew table (DPB_OFF) before SETSEC.
;   [RE] the 60K record->track/sector deblock; DPB geometry read from the LC low-page work cells.
;        [?] cross-checked against the 44K RECORD_TO_TRACK twin.
; ----------------------------------------------------------------------
RECORD_TO_TRACK:
        LD HL,CUR_BLOCK_NUMBER
        LD C,(HL)
        INC HL
        LD B,(HL)
        LD HL,(DEBLOCK_HSTREC_PTR1)
        LD E,(HL)
        INC HL
        LD D,(HL)
        LD HL,(DEBLOCK_HSTREC_PTR0)
        LD A,(HL)
        INC HL
        LD H,(HL)
        LD L,A
RECORD_TO_TRACK_1:
        LD A,C
        SUB E
        LD A,B
        SBC A,D
        JR NC,RECORD_TO_TRACK_2
        PUSH HL
        LD HL,(DPB_SPT)
        LD A,E
        SUB L
        LD E,A
        LD A,D
        SBC A,H
        LD D,A
        POP HL
        DEC HL
        JR RECORD_TO_TRACK_1
RECORD_TO_TRACK_2:
        PUSH HL
        LD HL,(DPB_SPT)
        ADD HL,DE
        JR C,RECORD_TO_TRACK_3
        LD A,C
        SUB L
        LD A,B
        SBC A,H
        JR C,RECORD_TO_TRACK_3
        EX DE,HL
        POP HL
        INC HL
        JR RECORD_TO_TRACK_2
RECORD_TO_TRACK_3:
        POP HL
        PUSH BC
        PUSH DE
        PUSH HL
        EX DE,HL
        LD HL,(DPB_OFF)
        ADD HL,DE
        LD B,H
        LD C,L
        CALL SETTRK
        POP DE
        LD HL,(DEBLOCK_HSTREC_PTR0)
        LD (HL),E
        INC HL
        LD (HL),D
        POP DE
        LD HL,(DEBLOCK_HSTREC_PTR1)
        LD (HL),E
        INC HL
        LD (HL),D
        POP BC
        LD A,C
        SUB E
        LD C,A
        LD A,B
        SBC A,D
        LD B,A
        LD HL,(DPB_XLT_PTR)
        EX DE,HL
        CALL SECTRAN
        LD C,L
        LD B,H
        JP SETSEC
; ----------------------------------------------------------------------
; REC_BLOCK_SHIFT_6 -- combine the FCB extent's low block-map bits with the record-in-block bits.
;   In: DPB block-shift BSH at $BFD0; the record-low and extent-low work bytes at $BFF0 / $BFEF.
;   Out: A = the composite index used by FCB_BLOCKMAP_INDEX_10 to pick the block-map slot.
;   Clobbers: A,B,C,flags.
;   Algorithm: shift the record byte (FCB_CURREC) right (8 - BSH) times, shift the extent byte (FCB_EXTENT_MASKED)
;       left BSH times, and add them to form the block-map slot index.
;   [RE] 60K deblock helper computing the FCB allocation-map slot from record + extent. [?]
; ----------------------------------------------------------------------
REC_BLOCK_SHIFT_6:
        LD HL,DPB_BSH
        LD C,(HL)
        LD A,(FCB_CURREC)
REC_BLOCK_SHIFT_6_1:
        OR A
        RRA
        DEC C
        JR NZ,REC_BLOCK_SHIFT_6_1
        LD B,A
        LD A,$08
        SUB (HL)
        LD C,A
        LD A,(FCB_EXTENT_MASKED)
REC_BLOCK_SHIFT_6_2:
        DEC C
        JR Z,REC_BLOCK_SHIFT_6_3
        OR A
        RLA
        JR REC_BLOCK_SHIFT_6_2
REC_BLOCK_SHIFT_6_3:
        ADD A,B
        RET
; ----------------------------------------------------------------------
; FCB_BLOCKMAP_INDEX_10 -- fetch the disk block number from the FCB allocation map at slot BC.
;   In: BC = slot index; current FCB pointer at $DF11 (upper-bank CURFCB cell); block-width flag $BFEA.
;   Out: HL = the block (group) number stored at FCB+$10+slot (8-bit map) or the 16-bit word there
;        (16-bit map, when $BFEA=0).  Clobbers: A,DE,HL,flags.
;   Algorithm: HL := (CURFCB $DF11) + $10 + BC; if $BFEA (narrow) nonzero read one byte (H:=0), else
;       add BC again and read the 16-bit word.
;   [RE] reads an FCB block-map entry; $BFEA selects 8-bit vs 16-bit block numbers. [DOC CP/M 2.2 FCB]
; ----------------------------------------------------------------------
FCB_BLOCKMAP_INDEX_10:
        LD HL,(BDOS_PARAM_PTR)
        LD DE,$0010
        ADD HL,DE
        ADD HL,BC
        LD A,(BLOCK_WIDTH_FLAG)
        OR A
        JR Z,FCB_BLOCKMAP_INDEX_10_1
        LD L,(HL)
        LD H,$00
        RET
FCB_BLOCKMAP_INDEX_10_1:
        ADD HL,BC
        LD E,(HL)
        INC HL
        LD D,(HL)
        EX DE,HL
        RET
; ----------------------------------------------------------------------
; REC_TO_BLOCK_14 -- map the current record to its disk block number via the FCB allocation map.
;   In: the record/extent work bytes ($BFF0/$BFEF) and current FCB (BDOS_PARAM_PTR).
;   Out: the block number for this record stored into the block work word $BFF2 (0 = unallocated).
;   Clobbers: A,BC,HL,flags.
;   Algorithm: REC_BLOCK_SHIFT_6 forms the block-map slot in A; C:=A,B:=0; FCB_BLOCKMAP_INDEX_10
;       reads that slot's block number; store to $BFF2.
;   [RE] 60K record->block lookup; feeds BLOCK_IS_ZERO_16 / BLOCK_BASE_RECORD_17. [?]
; ----------------------------------------------------------------------
REC_TO_BLOCK_14:
        CALL REC_BLOCK_SHIFT_6
        LD C,A
        LD B,$00
        CALL FCB_BLOCKMAP_INDEX_10
        LD (CUR_BLOCK_NUMBER),HL
        RET
; ----------------------------------------------------------------------
; BLOCK_IS_ZERO_16 -- test whether the current record's block (CUR_BLOCK_NUMBER) is unallocated.
;   In: block work word at $BFF2.
;   Out: A = L, Z set when the 16-bit block number is 0 (no block yet allocated for this record).
;   Clobbers: A,HL,flags.
;   Algorithm: HL := (CUR_BLOCK_NUMBER); A := L OR H; RET (Z <=> block==0).
;   [RE] the read/write core branches on Z here to decide allocate-vs-use. [?]
; ----------------------------------------------------------------------
BLOCK_IS_ZERO_16:
        LD HL,(CUR_BLOCK_NUMBER)
        LD A,L
        OR H
        RET
; ----------------------------------------------------------------------
; BLOCK_BASE_RECORD_17 -- compute the absolute base record of the current block plus the in-block record.
;   In: DPB block-shift BSH at $BFD0, block-mask BLM at $BFD1; block number at $BFF2; record-low $BFF0.
;   Out: $BFF4 = block# << BSH (the block's first record); $BFF2 = that base OR (record & BLM) = the
;        exact physical record.  Clobbers: A,C,HL,flags.
;   Algorithm: HL := block (CUR_BLOCK_NUMBER); ADD HL,HL BSH times to get the base record (stored $BFF4); then OR
;       in (record-low $BFF0 AND BLM $BFD1) and store the physical record back to $BFF2.
;   [RE] block-number -> physical-record fold used before RECORD_TO_TRACK. [?]
; ----------------------------------------------------------------------
BLOCK_BASE_RECORD_17:
        LD A,(DPB_BSH)
        LD HL,(CUR_BLOCK_NUMBER)
BLOCK_BASE_RECORD_17_1:
        ADD HL,HL
        DEC A
        JR NZ,BLOCK_BASE_RECORD_17_1
        LD (BLOCK_BASE_RECORD),HL
        LD A,(DPB_BLM)
        LD C,A
        LD A,(FCB_CURREC)
        AND C
        OR L
        LD L,A
        LD (CUR_BLOCK_NUMBER),HL
        RET
; ----------------------------------------------------------------------
; FCB_PTR_EXTENT -- point HL at the FCB's extent byte (FCB+$0C, the EX field).
;   In: current FCB pointer at $DF11 (upper-bank CURFCB cell).
;   Out: HL = CURFCB + $0C (the extent-number byte).  Clobbers: DE,HL.
;   Algorithm: HL := (BDOS_PARAM_PTR) + $000C.
;   [RE] FCB byte 12 = EX (extent number) per CP/M 2.2 FCB layout. [DOC CP/M 2.2 FCB]
; ----------------------------------------------------------------------
FCB_PTR_EXTENT:
        LD HL,(BDOS_PARAM_PTR)
        LD DE,$000C
        ADD HL,DE
        RET
; ----------------------------------------------------------------------
; FCB_PTR_RC_CR -- point DE at the FCB record-count byte (FCB+$0F) and HL at the current-record byte (FCB+$20).
;   In: current FCB pointer at $DF11.
;   Out: DE = CURFCB + $0F (RC, record count in the extent); HL = CURFCB + $20 (CR, current record).
;   Clobbers: DE,HL.
;   Algorithm: DE := (BDOS_PARAM_PTR) + $0F; HL := DE + $11 (= FCB + $20).
;   [RE] FCB byte 15 = RC, byte 32 = CR per CP/M 2.2 FCB layout. [DOC CP/M 2.2 FCB]
; ----------------------------------------------------------------------
FCB_PTR_RC_CR:
        LD HL,(BDOS_PARAM_PTR)
        LD DE,$000F
        ADD HL,DE
        EX DE,HL
        LD HL,$0011
        ADD HL,DE
        RET
; ----------------------------------------------------------------------
; FCB_PRIME_FIELDS -- load the current FCB's CR / RC / EX fields into the $BFxx deblock work bytes.
;   In: current FCB (BDOS_PARAM_PTR); DPB EXM mask at $BFD2.
;   Out: $BFF0 = CR (current record, FCB+$20); $BFEE = RC (record count, FCB+$0F); $BFEF = EX (extent,
;        FCB+$0C) masked with EXM.  Clobbers: A,DE,HL.
;   Algorithm: FCB_PTR_RC_CR gets the RC/CR pointers; copy CR->$BFF0 and RC->$BFEE; FCB_PTR_EXTENT
;       gets &EX; store (EX AND EXM $BFD2) -> $BFEF.
;   [RE] primes the working record/extent bytes the read/write core operates on. [?]
; ----------------------------------------------------------------------
FCB_PRIME_FIELDS:
        CALL FCB_PTR_RC_CR
        LD A,(HL)
        LD (FCB_CURREC),A
        EX DE,HL
        LD A,(HL)
        LD (FCB_RECCOUNT),A
        CALL FCB_PTR_EXTENT
        LD A,(DPB_EXM)
        AND (HL)
        LD (FCB_EXTENT_MASKED),A
        RET
; ----------------------------------------------------------------------
; FCB_WRITEBACK_REC -- write the working record/record-count bytes back into the current FCB.
;   In: working CR byte $BFF0, working RC byte $BFEE; write-type flag WRITE_TYPE=$BFE2.
;   Out: FCB CR (FCB+$20) := $BFF0 (+1 unless WRITE_TYPE=2 zero-fill); FCB RC (FCB+$0F) := $BFEE.
;   Clobbers: A,C,DE,HL.
;   Algorithm: FCB_PTR_RC_CR gets the pointers; C := 1 unless WRITE_TYPE (WRITE_TYPE_FLAG)==2 (then 0); store
;       (CR $BFF0 + C) to the FCB CR byte and RC $BFEE to the FCB RC byte.
;   [RE] post-I/O FCB position commit; WRITE_TYPE=2 (WRITEZF) does not advance CR. [?]
; ----------------------------------------------------------------------
FCB_WRITEBACK_REC:
        CALL FCB_PTR_RC_CR
        LD A,(WRITE_TYPE_FLAG)
        CP $02
        JR NZ,FCB_WRITEBACK_REC_1
        XOR A
FCB_WRITEBACK_REC_1:
        LD C,A
        LD A,(FCB_CURREC)
        ADD A,C
        LD (HL),A
        EX DE,HL
        LD A,(FCB_RECCOUNT)
        LD (HL),A
        RET
; ----------------------------------------------------------------------
; SHR_HL_C -- logical-shift HL right by C bit positions.
;   In: HL = value; C = shift count (0 leaves HL unchanged).
;   Out: HL >>= C.  Clobbers: C,HL (C decremented to 0).
;   Algorithm: INC C / loop { DEC C; ret if zero; SRL H; RR L }.
;   [RE] generic unsigned right-shift helper (record/4, drive-bit extraction). Mirror of SHL_HL_C.
; ----------------------------------------------------------------------
SHR_HL_C:
        INC C
SHR_HL_C_1:
        DEC C
        RET Z
        SRL H
        RR L
        JR SHR_HL_C_1
; ----------------------------------------------------------------------
; DIR_CHECKSUM -- compute the 128-byte additive checksum of the directory buffer.
;   In: the directory buffer pointer at $BFC6 (DIRBUF ptr).
;   Out: A = 8-bit sum of the 128 bytes.  Clobbers: A,C,HL.
;   Algorithm: C=$80 count, HL=(DIRBUF ptr $BFC6), A=0; loop ADD A,(HL)/INC HL/DEC C until C==0.
;   [RE] canonical CP/M directory-checksum routine (detects media swap). [DOC CP/M 2.2 ALG]
; ----------------------------------------------------------------------
DIR_CHECKSUM:
        LD C,$80
        LD HL,(DIRBUF_PTR)
        XOR A
DIR_CHECKSUM_LOOP:
        ADD A,(HL)
        INC HL
        DEC C
        JR NZ,DIR_CHECKSUM_LOOP
        RET
; ----------------------------------------------------------------------
; SHL_HL_C -- logical-shift HL left by C bit positions.
;   In: HL = value; C = shift count (0 leaves HL unchanged).
;   Out: HL <<= C.  Clobbers: C,HL (C decremented to 0).
;   Algorithm: INC C / loop { DEC C; ret if zero; ADD HL,HL }.
;   [RE] generic unsigned left-shift helper (e.g. building a 1<<n drive-bit mask).
; ----------------------------------------------------------------------
SHL_HL_C:
        INC C
SHL_HL_C_LOOP:
        DEC C
        RET Z
        ADD HL,HL
        JR SHL_HL_C_LOOP
; ----------------------------------------------------------------------
; DRIVE_BIT_OR_INTO_VECTOR -- OR the current drive's single-bit mask into a 16-bit vector.
;   In: BC = existing 16-bit vector (preserved); current drive at $DF10.
;       (HL on entry is IGNORED; it is overwritten with $0001.)
;   Out: HL = BC OR (1 << current_drive).  Clobbers: A,HL (BC saved/restored).
;   Algorithm: PUSH BC; C := current drive (BDOS_CUR_DRIVE); HL := 1; SHL_HL_C to form 1<<drive; POP BC;
;       L := C OR L, H := B OR H.
;   [RE] sets the current drive's bit in whatever vector the caller passes in BC (R/O and login
;   setters). [?]
; ----------------------------------------------------------------------
DRIVE_BIT_OR_INTO_VECTOR:
        PUSH BC
        LD A,(BDOS_CUR_DRIVE)
        LD C,A
        LD HL,$0001
        CALL SHL_HL_C
        POP BC
        LD A,C
        OR L
        LD L,A
        LD A,B
        OR H
        LD H,A
        RET
; ----------------------------------------------------------------------
; DRIVE_BIT_TEST -- test whether the current drive's bit is set in the read-only drive vector.
;   In: the 16-bit R/O vector at DRV_LOGIN_VECTOR ($BFBA, the read-only vector set by the
;       Write-Protect-Disk handler BDOS_F_SETRO); current drive at $DF10.
;   Out: A = 1 if the current drive's R/O bit is set, else 0; Z reflects the result.  Clobbers: A,C,HL.
;   Algorithm: load the vector (DRV_LOGIN_VECTOR), shift right by the drive number to bring its bit to bit 0, AND $01.
;   [RE] CHECK_DRIVE_READONLY raises the R/O error when this bit is set, proving the vector is the
;        read-only vector, not the login vector. [?] cell-name kept as DRV_LOGIN_VECTOR per the 44K twin.
; ----------------------------------------------------------------------
DRIVE_BIT_TEST:
        LD HL,(DRV_LOGIN_VECTOR)
        LD A,(BDOS_CUR_DRIVE)
        LD C,A
        CALL SHR_HL_C
        LD A,L
        AND $01
        RET
; ----------------------------------------------------------------------
; BDOS_F_SETRO -- BDOS function 28 (Write Protect Disk): set the current drive's R/O bit.
;   In: the R/O drive vector at DRV_LOGIN_VECTOR (DRV_LOGIN_VECTOR); current drive at $DF10; the directory
;       record-count limit word at (DPB_REC_PTR); a 16-bit working cell addressed by (DPB_WORK_PTR0).
;   Out: the R/O vector has the current drive's bit set; the word at (DPB_WORK_PTR0) := (record limit)+1.
;   Clobbers: A,BC,DE,HL.
;   Algorithm: load the R/O vector (DRV_LOGIN_VECTOR) into BC, set the current-drive bit via
;       DRIVE_BIT_OR_INTO_VECTOR, store it back; then store ((word at $BFD5)+1) into the cell at (DPB_WORK_PTR0).
;   [RE] this is the fn-28 entry ($DC8B->$B79B) in the dispatch table, confirming Write-Protect-Disk.
;        [?] reason for caching the record-limit+1 UNKNOWN.
; ----------------------------------------------------------------------
BDOS_F_SETRO:
        LD HL,DRV_LOGIN_VECTOR
        LD C,(HL)
        INC HL
        LD B,(HL)
        CALL DRIVE_BIT_OR_INTO_VECTOR
        LD (DRV_LOGIN_VECTOR),HL
        LD HL,(DPB_REC_PTR)
        INC HL
        EX DE,HL
        LD HL,(DPB_WORK_PTR0)
        LD (HL),E
        INC HL
        LD (HL),D
        RET
; ----------------------------------------------------------------------
; FCB_RO_FLAG_TEST -- raise the file-R/O error if the matched directory entry is read-only.
;   In: the DIRBUF ptr (DIRBUF_PTR) and entry byte-offset (DEBLOCK_BYTE_OFF) locate the matched entry (via
;       FCB_BUF_PTR_ADD_OFFSET).
;   Out: returns normally if writable; otherwise jumps to the BDOS error vector (no return; loads the
;        file-R/O error record at $DC0F and dispatches via $DF18).  Clobbers: A,DE,HL.
;   Algorithm: point at the entry, advance to byte +9 (the first type byte t1', whose bit 7 is the R/O
;       attribute), RLA to shift bit 7 into carry; RET NC if clear, else load HL=$DC0F (file-R/O error
;       block) and JP $DF18 (the BDOS error dispatch trampoline).
;   [RE] CP/M file R/O attribute = bit 7 of directory-entry byte 9 (t1'). [DOC CP/M 2.2 FCB]
; ----------------------------------------------------------------------
FCB_RO_FLAG_TEST:
        CALL FCB_BUF_PTR_ADD_OFFSET
; ----------------------------------------------------------------------
; CHECK_DIRENT_READONLY_INNER -- inner entry of FCB_RO_FLAG_TEST (HL already on the directory entry). [RE]
; ----------------------------------------------------------------------
CHECK_DIRENT_READONLY_INNER:
        LD DE,$0009
        ADD HL,DE
        LD A,(HL)
        RLA
        RET NC
        LD HL,$DC0F
        JP $DF18
; ----------------------------------------------------------------------
; CHECK_DRIVE_READONLY -- raise the disk-R/O error if the current drive is write-protected.
;   In: the current drive context (DRIVE_BIT_TEST reads the R/O drive vector at $BFBA).
;   Out: returns if writable; otherwise jumps to the BDOS error vector (no return; loads the disk-R/O
;        error record at $DC0D and dispatches via $DF18).  Clobbers: A,C,HL.
;   Algorithm: CALL DRIVE_BIT_TEST; RET Z if clear (writable), else HL := $DC0D (disk-R/O error block)
;       and JP $DF18 (the BDOS error dispatch trampoline).
;   [RE] guards writes against a write-protected disk. [?]
; ----------------------------------------------------------------------
CHECK_DRIVE_READONLY:
        CALL DRIVE_BIT_TEST
        RET Z
        LD HL,$DC0D
        JP $DF18
; ----------------------------------------------------------------------
; FCB_BUF_PTR_ADD_OFFSET -- compute a pointer to the matched directory entry inside the directory buffer.
;   In: DIRBUF ptr at $BFC6; the entry byte-offset at $BFF6.
;   Out: HL = (DIRBUF ptr) + offset.  Clobbers: A,HL.
;   Algorithm: load the buffer base (DIRBUF_PTR), load the 8-bit entry offset (DEBLOCK_BYTE_OFF), add it to L with carry
;       into H (falls into DIRENT_PTR_ADD).
;   [RE] locates the directory entry just matched by a BDOS directory search. [?]
; ----------------------------------------------------------------------
FCB_BUF_PTR_ADD_OFFSET:
        LD HL,(DIRBUF_PTR)
        LD A,(DEBLOCK_BYTE_OFF)
; ----------------------------------------------------------------------
; DIRENT_PTR_ADD -- add the 8-bit directory-entry offset in A to HL (carry into H). [RE]
; ----------------------------------------------------------------------
DIRENT_PTR_ADD:
        ADD A,L
        LD L,A
        RET NC
        INC H
        RET
; ----------------------------------------------------------------------
; FCB_GET_S2 -- point HL at FCB byte 14 (the S2 / extent-high field) of the current FCB.
;   In: current FCB pointer at $DF11 (upper-bank CURFCB cell).
;   Out: HL = (CURFCB $DF11) + $000E (FCB+14, the S2 byte); A = its current value.  Clobbers: A,DE,HL.
;   Algorithm: HL := base + $0E, read (HL) into A.
;   [RE] FCB byte 14 = S2 (extent-high / module count) per CP/M 2.2 FCB layout. [DOC CP/M 2.2 FCB]
; ----------------------------------------------------------------------
FCB_GET_S2:
        LD HL,(BDOS_PARAM_PTR)
        LD DE,$000E
        ADD HL,DE
        LD A,(HL)
        RET
; ----------------------------------------------------------------------
; F_MAKE_OPEN_PREP -- shared Open/Make preamble: reset the random-record scratch, clear S2, log in the FCB drive.
;   In: caller's FCB (DE set by the dispatcher; RANDREC_FIELD_RESET stages it into the scratch FCB).
;   Out: the random-record scratch FCB primed, the FCB S2 byte cleared, and the FCB's drive selected
;        (FCB_LOGIN_SELECT).  Clobbers: A,BC,DE,HL.
;   Algorithm: CALL RANDREC_FIELD_RESET; CALL CLEAR_FCB_S2; CALL FCB_LOGIN_SELECT; RET.
;   [RE] common front end of BDOS_F_OPEN (fn 15) and BDOS_F_MAKE (fn 22). [?]
; ----------------------------------------------------------------------
F_MAKE_OPEN_PREP:
        CALL RANDREC_FIELD_RESET
        CALL CLEAR_FCB_S2
        CALL FCB_LOGIN_SELECT
        RET
; ----------------------------------------------------------------------
; CLEAR_FCB_S2 -- zero the S2 (byte 14) field of the current FCB.
;   In: the current FCB (via FCB_GET_S2).  Out: FCB byte 14 = 0.  Clobbers: A,DE,HL.
;   Algorithm: get the S2 pointer, store 0.
;   [RE] resets the extent-high/S2 field. [DOC CP/M 2.2 FCB]
; ----------------------------------------------------------------------
CLEAR_FCB_S2:
        CALL FCB_GET_S2
        LD (HL),$00
        RET
; ----------------------------------------------------------------------
; MARK_FCB_S2_HIGHBIT -- set bit 7 of the FCB S2 (byte 14) field.
;   In: the current FCB (via FCB_GET_S2, which also returns A = the current S2 value).
;   Out: FCB byte 14 |= $80.  Clobbers: A,DE,HL.
;   Algorithm: get the S2 pointer (A = current S2), OR $80, store back.
;   [RE] in CP/M 2.2 the high bit of S2 flags the FCB as written / needing a directory update at close.
;        [DOC CP/M 2.2 FCB]
; ----------------------------------------------------------------------
MARK_FCB_S2_HIGHBIT:
        CALL FCB_GET_S2
        OR $80
        LD (HL),A
        RET
; ----------------------------------------------------------------------
; CMP_CURREC_VS_WORKPTR -- compare the current record number against the working record cell.
;   In: CUR_RECORD = 16-bit current record at $BFF7; the working-record word pointer at (DPB_WORK_PTR0).
;   Out: HL = address of the working value's high byte; flags = (CUR_RECORD - working value);
;        CARRY SET when CUR_RECORD < the working value.  Clobbers: A,DE,HL.
;   Algorithm: DE := (CUR_RECORD $BFF7), HL := (word at $BFC0); subtract low byte then high byte,
;       leaving HL on the high byte; no value is stored.
;   [RE] RECPTR_INC_STORE uses this: on NC it bumps and stores CUR_RECORD+1, extending the high-water
;   count. [?]
; ----------------------------------------------------------------------
CMP_CURREC_VS_WORKPTR:
        LD HL,(CUR_RECORD)
        EX DE,HL
        LD HL,(DPB_WORK_PTR0)
        LD A,E
        SUB (HL)
        INC HL
        LD A,D
        SBC A,(HL)
        RET
; ----------------------------------------------------------------------
; RECPTR_INC_STORE -- if the current record is at/past the stored high-water count, bump it one past.
;   In: CUR_RECORD = record just processed (CUR_RECORD); the working record-count word via (DPB_WORK_PTR0).
;   Out: if CUR_RECORD >= cell, cell := CUR_RECORD+1; else unchanged. DE = CUR_RECORD(+1 if updated);
;        HL in cell.  Clobbers: A,DE,HL,flags.
;   Algorithm: CMP_CURREC_VS_WORKPTR; RET C (CUR_RECORD < count, leave it); else DE:=CUR_RECORD+1 and
;       write it HIGH byte first (LD (HL),D), DEC HL, then LOW byte (LD (HL),E).
;   [RE] classic CP/M 2.2 extent record-count bump; keeps the FCB high-water one past the last accessed.
; ----------------------------------------------------------------------
RECPTR_INC_STORE:
        CALL CMP_CURREC_VS_WORKPTR
        RET C
        INC DE
        LD (HL),D
        DEC HL
        LD (HL),E
        RET
; ----------------------------------------------------------------------
; SUB16_DE_HL -- 16-bit subtract HL := DE - HL.
;   In: DE = minuend, HL = subtrahend.
;   Out: HL = DE - HL; carry set on borrow (DE < HL unsigned).  Clobbers: HL,flags. DE preserved.
;   Algorithm: EX DE,HL; OR A (clear carry); SBC HL,DE.
;   [RE] general BDOS 16-bit compare/difference helper used by the record scan and seek logic.
; ----------------------------------------------------------------------
SUB16_DE_HL:
        EX DE,HL
        OR A
        SBC HL,DE
        RET
; ----------------------------------------------------------------------
; RECORD_SCAN_BODY -- scan to the target byte in the cached directory record, then store or compare A there.
;   In: C = mode (INC C wraps to 0 => store mode, else compare); the scan cursor $BFF9 and limit $BFD9;
;       the entry byte-offset via $BFCA/$BFF9; A = byte to store/compare; DIRBUF holds the record.
;   Out: store mode writes A. Compare: Z on match; if no match and CUR_RECORD is past the stored count
;        it flags the drive R/O (BDOS_F_SETRO). NC if the scan cursor did not pass the limit.
;   Clobbers: A,BC,DE,HL,flags.
;   Algorithm: DE:=scan cursor (REC_CACHE), HL:=limit (REC_SCAN_PTR); SUB16_DE_HL; RET NC if the cursor passed.
;       Else DIR_CHECKSUM, add the offset (REC_BYTE_OFFSET) to $BFF9 to address the target byte. INC C: if it
;       wrapped to 0, store A; else CP (HL), RET Z on match; on mismatch CMP_CURREC_VS_WORKPTR; RET NC
;       if within count, else BDOS_F_SETRO.
;   [RE] heart of the directory record scan/checksum loop in the BDOS deblocking layer.
; ----------------------------------------------------------------------
RECORD_SCAN_BODY:
        LD C,$FF
RECORD_SCAN_BODY_1:
        LD HL,(REC_CACHE)
        EX DE,HL
        LD HL,(REC_SCAN_PTR)
        CALL SUB16_DE_HL
        RET NC
        PUSH BC
        CALL DIR_CHECKSUM
        LD HL,(REC_BYTE_OFFSET)
        EX DE,HL
        LD HL,(REC_CACHE)
        ADD HL,DE
        POP BC
        INC C
        JR Z,RECORD_SCAN_BODY_2
        CP (HL)
        RET Z
        CALL CMP_CURREC_VS_WORKPTR
        RET NC
        CALL BDOS_F_SETRO
        RET
RECORD_SCAN_BODY_2:
        LD (HL),A
        RET
; ----------------------------------------------------------------------
; DIR_RECORD_WRITE -- checksum-verify then write the directory buffer to disk as a record, and refresh the user buffer.
;   In: directory buffer (via DIRBUF ptr $BFC6) and the BDOS deblock state set up by the caller.
;   Out: the record is written to disk (with the R/O-on-tamper check); user DMA restored; errors raised
;        via the checked disk-write path.  Clobbers: A,BC,DE,HL,flags.
;   Algorithm: RECORD_SCAN_BODY runs the scan in store mode (re-checksums DIRBUF, sets the drive R/O on
;       a tamper mismatch). SET_DMA_TO_DISK_BUF aims the BIOS DMA at DIRBUF; C=1 selects the directory
;       write type; CALL $DF28 (the lower-LC checked-write trampoline) issues the BIOS WRITE; JR into
;       RESTORE_USER_DMA restores the user DMA.
;   [RE] directory-record write path; C=1 is the CP/M deblock directory-write code.
; ----------------------------------------------------------------------
DIR_RECORD_WRITE:
        CALL RECORD_SCAN_BODY
        CALL SET_DMA_TO_DISK_BUF
        LD C,$01
        CALL $DF28
        JR RESTORE_USER_DMA
; ----------------------------------------------------------------------
; DIR_RECORD_READ -- read a directory record from disk into the directory buffer, then restore the user DMA.
;   In: BDOS deblock state set up by the caller.
;   Out: DIRBUF filled from disk; user DMA restored.  Clobbers: A,BC,DE,HL,flags.
;   Algorithm: SET_DMA_TO_DISK_BUF, CALL $DF20 (the lower-LC checked-read trampoline: BIOS READ +
;       error check), then fall through into RESTORE_USER_DMA.
;   [RE] directory-record read path; pairs with DIR_RECORD_WRITE.
; ----------------------------------------------------------------------
DIR_RECORD_READ:
        CALL SET_DMA_TO_DISK_BUF
        CALL $DF20
; ----------------------------------------------------------------------
; RESTORE_USER_DMA -- restore the BIOS DMA address to the user's DMA buffer.
;   In: the DMA_ADDR cell at $BFBE holds the user DMA address.
;   Out: BIOS DMA set to (DMA_ADDR) via the BIOS SETDMA vector ($FA24).  Clobbers: BC,HL,flags.
;   Algorithm: HL := $BFBE (address of the DMA_ADDR cell), then load the word and JP BIOS SETDMA.
;   [RE] used after directory I/O to put DMA back to the application buffer.
; ----------------------------------------------------------------------
RESTORE_USER_DMA:
        LD HL,DMA_ADDR
        JR SET_DMA_FROM_CELL
; ----------------------------------------------------------------------
; SET_DMA_TO_DISK_BUF -- point the BIOS DMA at the directory/disk buffer (DIRBUF).
;   In: the DIRBUF ptr cell at $BFC6 holds the directory buffer address.
;   Out: BIOS DMA set to (DIRBUF ptr) via the BIOS SETDMA vector ($FA24).  Clobbers: BC,HL,flags.
;   Algorithm: HL := $BFC6 (address of the DIRBUF ptr cell); load the word and JP BIOS SETDMA.
;   [RE] companion to RESTORE_USER_DMA; aims I/O at the OS directory buffer.
; ----------------------------------------------------------------------
SET_DMA_TO_DISK_BUF:
        LD HL,DIRBUF_PTR
SET_DMA_FROM_CELL:
        LD C,(HL)
        INC HL
        LD B,(HL)
        JP SETDMA
SET_DMA_TO_DISK_BUF_2:
        LD HL,(DIRBUF_PTR)
        LD DE,(DMA_ADDR)
        LD BC,$0080
        CALL $DF3C
        RET
; ----------------------------------------------------------------------
; CUR_RECORD_BYTES_EQUAL -- test whether the low and high bytes of the 16-bit CUR_RECORD cell (CUR_RECORD) are equal.
;   In: CUR_RECORD = a 16-bit cell ($BFF7 low, $BFF8 high).
;   Out: if the two bytes differ, NZ with A = the low byte; if equal, A = low byte + 1.  Clobbers: A,HL,flags.
;   Algorithm: HL -> low byte (CUR_RECORD); A := (HL); INC HL; CP (HL); RET NZ if they differ; else INC A and RET.
;   [RE] deblock helper comparing the two halves of CUR_RECORD; called widely as an end-of-scan test.
;        The exact role of the equal/INC result is UNKNOWN from these bytes alone (callers consume Z).
; ----------------------------------------------------------------------
CUR_RECORD_BYTES_EQUAL:
        LD HL,CUR_RECORD
        LD A,(HL)
        INC HL
        CP (HL)
        RET NZ
        INC A
        RET
; ----------------------------------------------------------------------
; INVALIDATE_CUR_RECORD -- mark the cached record pointer invalid (CUR_RECORD := $FFFF).
;   In: none.  Out: CUR_RECORD cell (CUR_RECORD) = $FFFF.  Clobbers: HL.
;   Algorithm: HL := $FFFF; store to $BFF7; RET.
;   [RE] forces the next deblock access to reload, since $FFFF can never equal a real record number.
; ----------------------------------------------------------------------
INVALIDATE_CUR_RECORD:
        LD HL,$FFFF
        LD (CUR_RECORD),HL
        RET
; ----------------------------------------------------------------------
; DIR_READ_NEXT -- advance the directory record pointer and read the next 32-byte directory entry.
;   In: CUR_RECORD (CUR_RECORD) = last directory record index processed; the directory-record limit word at (DPB_REC_PTR).
;   Out: on a fresh 128-byte-record boundary the record is read into DIRBUF and the entry byte-offset
;        (DEBLOCK_BYTE_OFF) set to 0/32/64/96; at end of directory CUR_RECORD is invalidated ($FFFF).
;   Clobbers: A,BC,DE,HL,flags.
;   Algorithm: increment CUR_RECORD; SUB16_DE_HL against the limit (DPB_REC_PTR); if past the limit ->
;       INVALIDATE_CUR_RECORD; else offset := (CUR_RECORD & 3) << 5 into $BFF6, and on offset 0 compute
;       the disk record (REC_DIV4_SETUP) and DIR_RECORD_READ it into DIRBUF, then re-enter the scan.
;   [RE] canonical CP/M 2.2 read-next-directory-entry sequencer (four 32-byte entries per record).
; ----------------------------------------------------------------------
DIR_READ_NEXT:
        LD HL,(DPB_REC_PTR)
        EX DE,HL
        LD HL,(CUR_RECORD)
        INC HL
        LD (CUR_RECORD),HL
        CALL SUB16_DE_HL
        JR NC,DIR_RECORD_DEBLOCK
        JR INVALIDATE_CUR_RECORD
DIR_RECORD_DEBLOCK:
        LD A,(CUR_RECORD)
        AND $03
        LD B,$05
DIR_DEBLOCK_SHIFT:
        ADD A,A
        DJNZ DIR_DEBLOCK_SHIFT
        LD (DEBLOCK_BYTE_OFF),A
        OR A
        RET NZ
        PUSH BC
        CALL REC_DIV4_SETUP
        CALL DIR_RECORD_READ
        POP BC
        JP RECORD_SCAN_BODY_1
; ----------------------------------------------------------------------
; ALLOC_BIT_GET -- fetch the allocation-vector bit for a given disk block, returning it in carry.
;   In: BC = block (group) number; the allocation-vector base pointer at (ALLOC_VEC_PTR).
;   Out: carry/high bit of A = current allocation state; A = the allocation byte rotated so the wanted
;        bit is in the MSB; HL = address of that byte; D = E = bit index.  Clobbers: A,BC,DE,HL,flags.
;   Algorithm: D=E=(block & 7)+1 = 1-based bit index (rotate count); byte index = block >> 3; add to the
;       ALLOC-vec base (ALLOC_VEC_PTR); load the byte and rotate left by the bit index so the selected bit lands
;       in carry/MSB.
;   [RE] canonical CP/M 2.2 getmod: read one allocation bit from the bit-vector.
; ----------------------------------------------------------------------
ALLOC_BIT_GET:
        LD A,C
        AND $07
        INC A
        LD E,A
        LD D,A
        LD A,C
        RRCA
        RRCA
        RRCA
        AND $1F
        LD C,A
        LD A,B
        ADD A,A
        ADD A,A
        ADD A,A
        ADD A,A
        ADD A,A
        OR C
        LD C,A
        LD A,B
        RRCA
        RRCA
        RRCA
        AND $1F
        LD B,A
        LD HL,(ALLOC_VEC_PTR)
        ADD HL,BC
        LD A,(HL)
ALLOC_BIT_ROTATE:
        RLCA
        DEC E
        JR NZ,ALLOC_BIT_ROTATE
        RET
; ----------------------------------------------------------------------
; ALLOC_BIT_WRITE -- write one block's allocation-vector bit to a caller-supplied value.
;   In: BC = block (group) number; E = the bit value to store (1 = in use, 0 = free).
;   Out: that block's bit in the allocation vector is set to E. Clobbers: A,BC,DE,HL,flags.
;   Algorithm: PUSH DE saves the caller's value FIRST, because ALLOC_BIT_GET overwrites both
;       D and E with the bit index. ALLOC_BIT_GET returns the byte left-rotated so the target
;       bit is the LSB, HL pointing at it, and D = the rotate count. AND $FE clears that bit,
;       POP BC recovers the saved pair so C is the caller's value, and OR C writes it in;
;       ALLOC_BIT_RESTORE rotates back D times and stores.
;   The bit is NOT forced to 1 -- this is the one primitive for both directions, and which
;   direction it performs is entirely the caller's C. An earlier annotation here read "OR in 1
;   to set the target bit", which made the delete path look like it contradicted its own
;   comment. It does not: F_DELETE passes C=0 and frees, ALLOC_VECTOR_BUILD passes C=1. [RE]
; ----------------------------------------------------------------------
ALLOC_BIT_WRITE:
        PUSH DE
        CALL ALLOC_BIT_GET
        AND $FE
        POP BC
        OR C
; ----------------------------------------------------------------------
; ALLOC_BIT_RESTORE -- rotate the allocation byte right D times to restore alignment, then store it back. [RE]
; ----------------------------------------------------------------------
ALLOC_BIT_RESTORE:
        RRCA
        DEC D
        JR NZ,ALLOC_BIT_RESTORE
        LD (HL),A
        RET
; ----------------------------------------------------------------------
; ALLOC_FROM_FCB -- apply a directory entry's block map to the allocation vector.
;   In: C = the bit value to write for each block (1 = in use, 0 = free); it is stashed by
;       PUSH BC and recirculated through DE each iteration, reaching ALLOC_BIT_WRITE in E.
;       In: the entry byte-offset (DEBLOCK_BYTE_OFF) positions HL on the current 32-byte directory entry; block-width
;       flag $BFEA selects 8-bit (non-zero, DSM<256) vs 16-bit (zero) block numbers; entry holds a
;       16-byte block map at offset $10; max block DSM at (MAX_BLOCK_DSM).
;   Out: every non-zero, in-range block of this entry has its allocation bit set to the
;        CALLER'S value -- C=1 marks them in use (directory rebuild), C=0 frees them
;        (F_DELETE). The routine itself is direction-agnostic. Clobbers: A,BC,DE,HL,flags.
;   Algorithm: point HL at the block map (entry+$10); iterate 16 (8-bit) or 8 (16-bit) pointers; read
;       each block number; if non-zero and <= max block (MAX_BLOCK_DSM), mark it allocated via ALLOC_BIT_WRITE.
;   [RE] canonical CP/M 2.2 directory-entry allocation-map application used when rebuilding the alloc vector.
; ----------------------------------------------------------------------
ALLOC_FROM_FCB:
        CALL FCB_BUF_PTR_ADD_OFFSET
        LD DE,$0010
        ADD HL,DE
        PUSH BC
        LD C,$11
ALLOC_FROM_FCB_LOOP:
        POP DE
        DEC C
        RET Z
        PUSH DE
        LD A,(BLOCK_WIDTH_FLAG)
        OR A
        JR Z,ALLOC_FROM_FCB_WIDE
        PUSH BC
        PUSH HL
        LD C,(HL)
        LD B,$00
        JR ALLOC_FROM_FCB_CHECK
ALLOC_FROM_FCB_WIDE:
        DEC C
        PUSH BC
        LD C,(HL)
        INC HL
        LD B,(HL)
        PUSH HL
ALLOC_FROM_FCB_CHECK:
        LD A,C
        OR B
        JR Z,ALLOC_FROM_FCB_NEXT
        LD HL,(MAX_BLOCK_DSM)
        LD A,L
        SUB C
        LD A,H
        SBC A,B
        CALL NC,ALLOC_BIT_WRITE
ALLOC_FROM_FCB_NEXT:
        POP HL
        INC HL
        POP BC
        JR ALLOC_FROM_FCB_LOOP
; ----------------------------------------------------------------------
; ALLOC_VECTOR_BUILD -- rebuild the drive's allocation bit-vector by scanning the entire directory.
;   In: selected drive's DPB fields (max block DSM at $BFD3, directory-reserved-blocks word at $BFD7,
;       ALLOC-vec base at $BFCC).
;   Out: allocation vector fully populated: reserved directory blocks plus every block referenced by a
;        non-deleted directory entry are marked used.  Clobbers: A,BC,DE,HL,flags.
;   Algorithm: zero the allocation vector across its whole length ((DSM+1)/8 bytes); seed the reserved
;       directory blocks (ALLOC_END_PTR); reset the scan workspace to read from the start (DISK_HOME_CLEAR_SCAN);
;       for each entry skip deleted ($E5) ones, run a special-entry check against the current user
;       (BDOS_STACK_TOP) / '$' ($24) name byte (storing into the result cell $DF13), and ALLOC_FROM_FCB to mark
;       its blocks; advance until the directory is exhausted.
;   [RE] canonical CP/M 2.2 drive-init allocation-vector builder, invoked on drive selection / reset.
;   [?] the user-byte / '$' name-byte special-entry path's exact intent is UNKNOWN.
; ----------------------------------------------------------------------
ALLOC_VECTOR_BUILD:
        LD HL,(MAX_BLOCK_DSM)
        LD C,$03
        CALL SHR_HL_C
        INC HL
        LD B,H
        LD C,L
        LD HL,(ALLOC_VEC_PTR)
ALLOC_VECTOR_CLEAR_LOOP:
        LD (HL),$00
        INC HL
        DEC BC
        LD A,B
        OR C
        JR NZ,ALLOC_VECTOR_CLEAR_LOOP
        LD HL,(ALLOC_END_PTR)
        EX DE,HL
        LD HL,(ALLOC_VEC_PTR)
        LD (HL),E
        INC HL
        LD (HL),D
        CALL DISK_HOME_CLEAR_SCAN
        LD HL,(DPB_WORK_PTR0)
        LD (HL),$03
        INC HL
        LD (HL),$00
        CALL INVALIDATE_CUR_RECORD
ALLOC_VECTOR_SCAN_LOOP:
        LD C,$FF
        CALL DIR_READ_NEXT
        CALL CUR_RECORD_BYTES_EQUAL
        RET Z
        CALL FCB_BUF_PTR_ADD_OFFSET
        LD A,$E5
        CP (HL)
        JR Z,ALLOC_VECTOR_SCAN_LOOP
        LD A,(BDOS_STACK_TOP)
        CP (HL)
        JR NZ,ALLOC_VECTOR_SCAN_MARK
        INC HL
        LD A,(HL)
        SUB $24
        JR NZ,ALLOC_VECTOR_SCAN_MARK
        DEC A
        LD (BDOS_RETVAL),A
ALLOC_VECTOR_SCAN_MARK:
        LD C,$01
        CALL ALLOC_FROM_FCB
        CALL RECPTR_INC_STORE
        JP ALLOC_VECTOR_SCAN_LOOP
; ----------------------------------------------------------------------
; DIR_RETURN_MATCH_FLAG -- return the saved directory-search match status as the BDOS result.
;   In: the directory match flag at $BFE1 ($FF=no match, else the 0..3 entry index).
;   Out: A = (DIR_MATCH_FLAG); stored to the BDOS result byte via the common result-store path ($DED0).  Clobbers: A.
;   Algorithm: load the cached search-match flag (DIR_MATCH_FLAG) and JP BDOS_RET_RESULT (the upper-bank BDOS_RET_RESULT).
;   [RE] common return tail of F_DELETE_HND / F_RENAME_HND / F_ATTRIB_HND.
; ----------------------------------------------------------------------
DIR_RETURN_MATCH_FLAG:
        LD A,(DIR_MATCH_FLAG)
        JP BDOS_RET_RESULT
; ----------------------------------------------------------------------
; FCB_EXTENT_COMPARE -- compare two FCB extent bytes under the drive's extent mask.
;   In: C = one extent byte; A = the other extent byte; DPB EXM mask at $BFD2.
;   Out: A,flags = ((A & ~mask) - (C & ~mask)) & $1F; Z set when the high extent fields match.  Clobbers: A (BC/AF saved+restored).
;   Algorithm: complement EXM (DPB_EXM), AND it into both extent bytes (dropping the masked low bits),
;       subtract, keep five bits, and test for equality.
;   [RE]
; ----------------------------------------------------------------------
FCB_EXTENT_COMPARE:
        PUSH BC
        PUSH AF
        LD A,(DPB_EXM)
        CPL
        LD B,A
        LD A,C
        AND B
        LD C,A
        POP AF
        AND B
        SUB C
        AND $1F
        POP BC
        RET
; ----------------------------------------------------------------------
; DIR_SEARCH_FIRST -- begin a directory scan for the current FCB, comparing C bytes per entry.
;   In: C = number of FCB bytes to match ($0C=name+type, $0F=incl. extent); current FCB at $DF11.
;   Out: falls through into BDOS_DIR_SCAN_NEXT, which returns the within-record entry index 0..3 or $FF.
;   Clobbers: A,B,C,D,E,H,L,flags.
;   Algorithm: set the match flag $BFE1=$FF, store the compare length (DIR_CMP_LEN) and search-FCB pointer
;       (DIR_FCB_PTR), reset the record counter to -1 (INVALIDATE_CUR_RECORD), rewind/clear the scan state
;       (DISK_HOME_CLEAR_SCAN), then run the first pass.
;   [RE]
; ----------------------------------------------------------------------
DIR_SEARCH_FIRST:
        LD A,$FF
        LD (DIR_MATCH_FLAG),A
        LD HL,DIR_CMP_LEN
        LD (HL),C
        LD HL,(BDOS_PARAM_PTR)
        LD (DIR_FCB_PTR),HL
        CALL INVALIDATE_CUR_RECORD
        CALL DISK_HOME_CLEAR_SCAN
; ----------------------------------------------------------------------
; BDOS_DIR_SCAN_NEXT -- advance through directory entries until one matches the search FCB.
;   In: search-FCB pointer at $BFE6; compare length at $BFE5.
;   Out: A = matching entry index (0..3, stored to result cell $DF13) on success; not-found via the
;        $FF result path.  Clobbers: A,B,C,D,E,H,L,flags.
;   Algorithm: step to the next directory record (DIR_READ_NEXT); if the counter passed the directory
;       limit -> not found; otherwise treat erased ($E5) entries specially and bound-check
;       (CMP_CURREC_VS_WORKPTR), then compare C bytes per entry (with '?' $3F wildcards and EXM-masked
;       extent compare); on full match -> return the index, else loop to the next entry/record.
;   [RE] standard CP/M 2.2 directory search-next with '?' wildcards.
; ----------------------------------------------------------------------
BDOS_DIR_SCAN_NEXT:
        LD C,$00
        CALL DIR_READ_NEXT
        CALL CUR_RECORD_BYTES_EQUAL
        JR Z,DIR_NO_MATCH
        LD HL,(DIR_FCB_PTR)
        EX DE,HL
        LD A,(DE)
        CP $E5
        JR Z,BDOS_DIR_SCAN_NEXT_CMP
        PUSH DE
        CALL CMP_CURREC_VS_WORKPTR
        POP DE
        JR NC,DIR_NO_MATCH
BDOS_DIR_SCAN_NEXT_CMP:
        CALL FCB_BUF_PTR_ADD_OFFSET
        LD A,(DIR_CMP_LEN)
        LD C,A
        LD B,$00
DIR_CMP_BYTE_LOOP:
        LD A,C
        OR A
        JR Z,DIR_MATCH_FOUND
        LD A,(DE)
        CP $3F
        JR Z,DIR_CMP_ADVANCE
        LD A,B
        CP $0D
        JR Z,DIR_CMP_ADVANCE
        CP $0C
        LD A,(DE)
        JR Z,DIR_CMP_EXTENT
        SUB (HL)
        AND $7F
        JR NZ,BDOS_DIR_SCAN_NEXT
        JR DIR_CMP_ADVANCE
DIR_CMP_EXTENT:
        PUSH BC
        LD C,(HL)
        CALL FCB_EXTENT_COMPARE
        POP BC
        JR NZ,BDOS_DIR_SCAN_NEXT
DIR_CMP_ADVANCE:
        INC DE
        INC HL
        INC B
        DEC C
        JR DIR_CMP_BYTE_LOOP
DIR_MATCH_FOUND:
        LD A,(CUR_RECORD)
        AND $03
        LD (BDOS_RETVAL),A
        LD HL,DIR_MATCH_FLAG
        LD A,(HL)
        RLA
        RET NC
        XOR A
        LD (HL),A
        RET
DIR_NO_MATCH:
        CALL INVALIDATE_CUR_RECORD
        LD A,$FF
        JP BDOS_RET_RESULT
; ----------------------------------------------------------------------
; F_DELETE_HND -- delete every directory entry matching the FCB (worker for BDOS function 19).
;   In: current FCB at $DF11 (may contain '?' wildcards).
;   Out: matching directory entries marked erased ($E5), their blocks freed, and written back.
;   Clobbers: A,B,C,D,E,H,L,flags.
;   Algorithm: CHECK_DRIVE_READONLY, DIR_SEARCH_FIRST on 12 FCB bytes (name+type), then loop: for each
;       match test the R/O flag (FCB_RO_FLAG_TEST), stamp the entry byte $E5, free its blocks
;       (ALLOC_FROM_FCB with C=0), DIR_RECORD_WRITE, BDOS_DIR_SCAN_NEXT.
;   [RE] CP/M 2.2 F_DELETE.
; ----------------------------------------------------------------------
F_DELETE_HND:
        CALL CHECK_DRIVE_READONLY
        LD C,$0C
        CALL DIR_SEARCH_FIRST
F_DELETE_LOOP:
        CALL CUR_RECORD_BYTES_EQUAL
        RET Z
        CALL FCB_RO_FLAG_TEST
        CALL FCB_BUF_PTR_ADD_OFFSET
        LD (HL),$E5
        LD C,$00
        CALL ALLOC_FROM_FCB
        CALL DIR_RECORD_WRITE
        CALL BDOS_DIR_SCAN_NEXT
        JR F_DELETE_LOOP
; ----------------------------------------------------------------------
; ALLOC_GET_BLOCK -- find/allocate a disk block near a starting block, marking it used.
;   In: BC = starting block number (passed by the write core when extending a file); max block DSM at (MAX_BLOCK_DSM).
;   Out: HL = the block number actually claimed (0 if none free); its allocation-vector bit set.  Clobbers: A,B,C,D,E,H,L,flags.
;   Algorithm: copy the start block to DE, scan downward then upward testing each block's allocation bit
;       (ALLOC_BIT_GET), bounded by max block (MAX_BLOCK_DSM); mark the chosen block used (ALLOC_BIT_RESTORE)
;       and return it, or 0 when no block can be allocated.
;   [RE] allocation-vector block search/allocate.
; ----------------------------------------------------------------------
ALLOC_GET_BLOCK:
        LD D,B
        LD E,C
ALLOC_SCAN_DOWN:
        LD A,C
        OR B
        JR Z,ALLOC_SCAN_UP
        DEC BC
        PUSH DE
        PUSH BC
        CALL ALLOC_BIT_GET
        RRA
        JR NC,ALLOC_MARK_DONE
        POP BC
        POP DE
ALLOC_SCAN_UP:
        LD HL,(MAX_BLOCK_DSM)
        LD A,E
        SUB L
        LD A,D
        SBC A,H
        JR NC,ALLOC_SCAN_FINISH
        INC DE
        PUSH BC
        PUSH DE
        LD B,D
        LD C,E
        CALL ALLOC_BIT_GET
        RRA
        JR NC,ALLOC_MARK_DONE
        POP DE
        POP BC
        JR ALLOC_SCAN_DOWN
ALLOC_MARK_DONE:
        RLA
        INC A
        CALL ALLOC_BIT_RESTORE
        POP HL
        POP DE
        RET
ALLOC_SCAN_FINISH:
        LD A,C
        OR B
        JR NZ,ALLOC_SCAN_DOWN
        LD HL,$0000
        RET
; ----------------------------------------------------------------------
; FCB_WRITE_DIR_ENTRY -- copy the whole 32-byte FCB image into the matched directory entry and write it.
;   In: current FCB at $DF11; sets C=0 (FCB offset 0), E=$20 (32 bytes).
;   Out: directory record holding this entry written back to disk.  Clobbers: A,B,C,D,E,H,L,flags.
;   Algorithm: set up a full-32-byte copy at FCB offset 0 and fall into FCB_COPY_TO_DIR.
;   [RE]
; ----------------------------------------------------------------------
FCB_WRITE_DIR_ENTRY:
        LD C,$00
        LD E,$20
; ----------------------------------------------------------------------
; FCB_COPY_TO_DIR -- copy E FCB bytes (from offset C) into the matched directory entry.
;   In: C = FCB byte offset; E = byte count; current FCB at $DF11; current matched dir entry.
;   Out: directory buffer updated, then the record written via FCB_FLUSH_DIR.  Clobbers: A,B,C,D,E,H,L,flags.
;   Algorithm: form a source pointer at FCB+C ($DF11 + C), point HL at the directory entry slot
;       (FCB_BUF_PTR_ADD_OFFSET), block-copy E bytes, then fall into FCB_FLUSH_DIR to commit the record.
;   [RE]
; ----------------------------------------------------------------------
FCB_COPY_TO_DIR:
        PUSH DE
        LD B,$00
        LD HL,(BDOS_PARAM_PTR)
        ADD HL,BC
        EX DE,HL
        CALL FCB_BUF_PTR_ADD_OFFSET
        POP BC
        LD B,$00
        EX DE,HL
        LDIR
; ----------------------------------------------------------------------
; FCB_FLUSH_DIR -- position to the directory record and write it back.
;   In: current directory record state from the preceding match.  Out: the directory record written to disk.
;   Clobbers: A,B,C,D,E,H,L,flags.
;   Algorithm: REC_DIV4_SETUP positions on the 128-byte record holding the entry, then tail-jump to
;       DIR_RECORD_WRITE.
;   [RE]
; ----------------------------------------------------------------------
FCB_FLUSH_DIR:
        CALL REC_DIV4_SETUP
        JP DIR_RECORD_WRITE
; ----------------------------------------------------------------------
; F_RENAME_HND -- rename a file: replace matching directory entries with the new name (worker for BDOS fn 23).
;   In: current FCB at $DF11 whose bytes 0..15 are the old name and bytes 16..31 the new name.
;   Out: every matching directory entry rewritten with the new name; read-only entries rejected.
;   Clobbers: A,B,C,D,E,H,L,flags.
;   Algorithm: CHECK_DRIVE_READONLY, DIR_SEARCH_FIRST on 12 bytes of the old name, copy the FCB drive
;       byte (offset 0) into the new-name half (offset 16) so both target the same drive, then loop:
;       R/O-test each match and FCB_COPY_TO_DIR of 12 bytes from FCB offset $10 into the entry.
;   [RE] CP/M 2.2 F_RENAME.
; ----------------------------------------------------------------------
F_RENAME_HND:
        CALL CHECK_DRIVE_READONLY
        LD C,$0C
        CALL DIR_SEARCH_FIRST
        LD HL,(BDOS_PARAM_PTR)
        LD A,(HL)
        LD DE,$0010
        ADD HL,DE
        LD (HL),A
F_RENAME_LOOP:
        CALL CUR_RECORD_BYTES_EQUAL
        RET Z
        CALL FCB_RO_FLAG_TEST
        LD C,$10
        LD E,$0C
        CALL FCB_COPY_TO_DIR
        CALL BDOS_DIR_SCAN_NEXT
        JR F_RENAME_LOOP
; ----------------------------------------------------------------------
; F_ATTRIB_HND -- set file attributes from the FCB into matching directory entries (worker for BDOS fn 30).
;   In: current FCB at $DF11 carrying the attribute high bits in the name/type bytes.
;   Out: every matching directory entry's first 12 bytes rewritten with the FCB's attribute bits.
;   Clobbers: A,B,C,D,E,H,L,flags.
;   Algorithm: DIR_SEARCH_FIRST on 12 bytes, then loop FCB_COPY_TO_DIR of the 12 name/type bytes (with
;       attribute high bits) from FCB offset 0 into each matched entry and write the record.
;   [RE] CP/M 2.2 F_ATTRIB.
; ----------------------------------------------------------------------
F_ATTRIB_HND:
        LD C,$0C
        CALL DIR_SEARCH_FIRST
F_ATTRIB_LOOP:
        CALL CUR_RECORD_BYTES_EQUAL
        RET Z
        LD C,$00
        LD E,$0C
        CALL FCB_COPY_TO_DIR
        CALL BDOS_DIR_SCAN_NEXT
        JR F_ATTRIB_LOOP
; ----------------------------------------------------------------------
; FILE_OPEN_SEARCH -- search-first for the FCB's extent and merge the directory entry into the FCB.
;   In: current FCB at $DF11. Core of BDOS_F_OPEN (fn 15) and the random-record extent-positioning path.
;   Out: on match, the matched entry is merged into the FCB (record-count fields filled, FILE_SIZE_FROM_EXTENT);
;        on no match returns Z with no merge.  Clobbers: A,B,C,D,E,H,L,flags.
;   Algorithm: DIR_SEARCH_FIRST on 15 bytes (name+type+extent); CUR_RECORD_BYTES_EQUAL; if not found
;       return Z; otherwise fall through into FILE_SIZE_FROM_EXTENT to copy the entry into the FCB and set the
;       record count.
;   [RE] CP/M 2.2 F_OPEN core / extent locate-and-merge.
; ----------------------------------------------------------------------
FILE_OPEN_SEARCH:
        LD C,$0F
        CALL DIR_SEARCH_FIRST
        CALL CUR_RECORD_BYTES_EQUAL
        RET Z
; ----------------------------------------------------------------------
; FILE_SIZE_FROM_EXTENT -- merge a matched directory entry into the FCB and update its record count.
;   In: HL positioned via FCB_PTR_EXTENT on the FCB extent byte; current FCB at $DF11; the matched dir entry.
;   Out: the 32-byte entry copied into the FCB image; the FCB's record-count byte (offset $0F) set to $00
;        if this extent is below the current one, RC if equal, $80 if above; S2 'written' bit set.
;   Clobbers: A,B,C,D,E,H,L,flags.
;   Algorithm: save the FCB extent byte; FCB_BUF_PTR_ADD_OFFSET -> the dir entry; LDIR 32 bytes into the
;       FCB (BDOS_PARAM_PTR); MARK_FCB_S2_HIGHBIT; read dir-entry EX (offset $0C) and RC (offset $0F), compare
;       against the saved FCB extent, and store the chosen record-count byte at FCB+$0F.
;   [RE] used by both F_OPEN (FILE_OPEN_SEARCH) and F_SIZE. Twin of the 44K FILE_SIZE_FROM_EXTENT.
; ----------------------------------------------------------------------
FILE_SIZE_FROM_EXTENT:
        CALL FCB_PTR_EXTENT
        LD A,(HL)
        PUSH AF
        PUSH HL
        CALL FCB_BUF_PTR_ADD_OFFSET
        LD DE,(BDOS_PARAM_PTR)
        LD BC,$0020
        PUSH DE
        LDIR
        CALL MARK_FCB_S2_HIGHBIT
        POP DE
        LD HL,$000C
        ADD HL,DE
        LD C,(HL)
        LD HL,$000F
        ADD HL,DE
        LD B,(HL)
        POP HL
        POP AF
        LD (HL),A
        LD A,C
        CP (HL)
        LD A,B
        JR Z,FILE_SIZE_STORE
        LD A,$00
        JR C,FILE_SIZE_STORE
        LD A,$80
FILE_SIZE_STORE:
        LD HL,(BDOS_PARAM_PTR)
        LD DE,$000F
        ADD HL,DE
        LD (HL),A
        RET
; ----------------------------------------------------------------------
; FCB_WORD_FILL_IF_ZERO -- copy a 16-bit word from (DE) to (HL) only when (HL) is currently zero.
;   In: HL -> destination word; DE -> source word.
;   Out: if the destination word was 0, it is overwritten with the source word; DE,HL preserved.  Clobbers: A,flags.
;   Algorithm: OR the two destination bytes; if non-zero return unchanged; otherwise copy both source
;       bytes across, restoring DE/HL to their entry values.
;   [RE] allocation-word merge helper used during F_CLOSE_HND.
; ----------------------------------------------------------------------
FCB_WORD_FILL_IF_ZERO:
        LD A,(HL)
        INC HL
        OR (HL)
        DEC HL
        RET NZ
        LD A,(DE)
        LD (HL),A
        INC DE
        INC HL
        LD A,(DE)
        LD (HL),A
        DEC DE
        DEC HL
        RET
; ----------------------------------------------------------------------
; F_CLOSE_HND -- close a file: merge the in-memory FCB into its directory entry (worker for BDOS fn 16).
;   In: current FCB at $DF11. Also used internally to flush an extent.
;   Out: directory entry updated with this FCB's allocation map / record count; result byte (BDOS_RETVAL) set.
;   Clobbers: A,B,C,D,E,H,L,flags.
;   Algorithm: zero the result byte (BDOS_RETVAL) and record state, verify the drive is selected (DRIVE_BIT_TEST)
;       and the FCB S2 high bit is clear; DIR_SEARCH_FIRST on the extent (15 bytes); if found, merge the
;       FCB's 16-byte allocation map into the entry (filling zero words via FCB_WORD_FILL_IF_ZERO, keeping
;       the larger record count) then flush (FCB_FLUSH_DIR).
;   [RE] CP/M 2.2 F_CLOSE.
; ----------------------------------------------------------------------
F_CLOSE_HND:
        XOR A
        LD (BDOS_RETVAL),A
        LD (CUR_RECORD),A
        LD (CUR_RECORD_HI),A
        CALL DRIVE_BIT_TEST
        RET NZ
        CALL FCB_GET_S2
        AND $80
        RET NZ
        LD C,$0F
        CALL DIR_SEARCH_FIRST
        CALL CUR_RECORD_BYTES_EQUAL
        RET Z
        LD BC,$0010
        CALL FCB_BUF_PTR_ADD_OFFSET
        ADD HL,BC
        EX DE,HL
        LD HL,(BDOS_PARAM_PTR)
        ADD HL,BC
        LD C,$10
FCB_MERGE_MAP_LOOP:
        LD A,(BLOCK_WIDTH_FLAG)
        OR A
        JR Z,FCB_MERGE_WORD
        LD A,(HL)
        OR A
        LD A,(DE)
        JR NZ,F_CLOSE_HND_2
        LD (HL),A
F_CLOSE_HND_2:
        OR A
        JR NZ,F_CLOSE_HND_3
        LD A,(HL)
        LD (DE),A
F_CLOSE_HND_3:
        CP (HL)
        JR NZ,FCB_DEC_RESULT
        JR FCB_MERGE_NEXT
FCB_MERGE_WORD:
        CALL FCB_WORD_FILL_IF_ZERO
        EX DE,HL
        CALL FCB_WORD_FILL_IF_ZERO
        EX DE,HL
        LD A,(DE)
        CP (HL)
        JR NZ,FCB_DEC_RESULT
        INC DE
        INC HL
        LD A,(DE)
        CP (HL)
        JR NZ,FCB_DEC_RESULT
        DEC C
FCB_MERGE_NEXT:
        INC DE
        INC HL
        DEC C
        JR NZ,FCB_MERGE_MAP_LOOP
        LD BC,$FFEC
        ADD HL,BC
        EX DE,HL
        ADD HL,BC
        LD A,(DE)
        CP (HL)
        JR C,FCB_MERGE_FINISH
        LD (HL),A
        LD BC,$0003
        ADD HL,BC
        EX DE,HL
        ADD HL,BC
        LD A,(HL)
        LD (DE),A
FCB_MERGE_FINISH:
        LD A,$FF
        LD (DIR_DIRTY_FLAG),A
        JP FCB_FLUSH_DIR
FCB_DEC_RESULT:
        LD HL,BDOS_RETVAL
        DEC (HL)
        RET
; ----------------------------------------------------------------------
; DIR_MAKE_ENTRY -- find a free directory slot and create a new (empty) entry for the FCB (worker for BDOS fn 22).
;   In: current FCB at $DF11.
;   Out: a free directory slot located and initialized for this file; returns Z if no slot is free.
;   Clobbers: A,B,C,D,E,H,L,flags.
;   Algorithm: CHECK_DRIVE_READONLY, temporarily redirect the FCB pointer (BDOS_PARAM_PTR) to the scratch
;       EMPTY_DIR_FCB and DIR_SEARCH_FIRST in mode 1 for an empty ($E5) slot, restore the FCB pointer; on
;       success zero 17 bytes of the entry's record/allocation area (from offset $0F), clear the S1 byte
;       (offset $0D), advance the record pointer (RECPTR_INC_STORE), write the new entry
;       (FCB_WRITE_DIR_ENTRY), and set the FCB S2 'written' flag.
;   [RE] make-directory-entry helper.
; ----------------------------------------------------------------------
DIR_MAKE_ENTRY:
        CALL CHECK_DRIVE_READONLY
        LD HL,(BDOS_PARAM_PTR)
        PUSH HL
        LD HL,EMPTY_DIR_FCB
        LD (BDOS_PARAM_PTR),HL
        LD C,$01
        CALL DIR_SEARCH_FIRST
        CALL CUR_RECORD_BYTES_EQUAL
        POP HL
        LD (BDOS_PARAM_PTR),HL
        RET Z
        EX DE,HL
        LD HL,$000F
        ADD HL,DE
        LD C,$11
        XOR A
DIR_ZERO_ALLOC:
        LD (HL),A
        INC HL
        DEC C
        JR NZ,DIR_ZERO_ALLOC
        LD HL,$000D
        ADD HL,DE
        LD (HL),A
        CALL RECPTR_INC_STORE
        CALL FCB_WRITE_DIR_ENTRY
        JP MARK_FCB_S2_HIGHBIT
; ----------------------------------------------------------------------
; FCB_ADVANCE_RECORD -- advance the FCB to the next record/extent for sequential access.
;   In: current FCB at $DF11; DPB EXM mask at $BFD2; the dir-changed flag $BFDF.
;   Out: FCB current-record / extent fields stepped; new extent opened or created as needed; result $DF13.
;   Clobbers: A,B,C,D,E,H,L,flags.
;   Algorithm: clear the dir-changed flag (DIR_DIRTY_FLAG), flush the current extent (F_CLOSE_HND), bump the FCB
;       extent byte (offset $0C) mod 32; on wrap step the S2 module (offset $0E); otherwise use the EXM
;       mask (DPB_EXM) and the dir-changed flag to decide between re-opening the current extent
;       (FILE_OPEN_SEARCH / DIR_MAKE_ENTRY) or merging the just-flushed one (FILE_SIZE_FROM_EXTENT).
;   [RE] sequential-access record/extent advance.
; ----------------------------------------------------------------------
FCB_ADVANCE_RECORD:
        XOR A
        LD (DIR_DIRTY_FLAG),A
        CALL F_CLOSE_HND
        CALL CUR_RECORD_BYTES_EQUAL
        RET Z
        LD HL,(BDOS_PARAM_PTR)
        LD BC,$000C
        ADD HL,BC
        LD A,(HL)
        INC A
        AND $1F
        LD (HL),A
        JR Z,FCB_NEXT_EXTENT
        LD B,A
        LD A,(DPB_EXM)
        AND B
        LD HL,DIR_DIRTY_FLAG
        AND (HL)
        JR Z,FCB_ADVANCE_RECORD_2
        JR FCB_ADVANCE_RECORD_3
FCB_NEXT_EXTENT:
        LD BC,$0002
        ADD HL,BC
        INC (HL)
        LD A,(HL)
        AND $0F
        JR Z,FCB_ADVANCE_RECORD_5
FCB_ADVANCE_RECORD_2:
        LD C,$0F
        CALL DIR_SEARCH_FIRST
        CALL CUR_RECORD_BYTES_EQUAL
        JR NZ,FCB_ADVANCE_RECORD_3
        LD A,(RW_DIRECTION_FLAG)
        INC A
        JR Z,FCB_ADVANCE_RECORD_5
        CALL DIR_MAKE_ENTRY
        CALL CUR_RECORD_BYTES_EQUAL
        JR Z,FCB_ADVANCE_RECORD_5
        JR FCB_ADVANCE_RECORD_4
FCB_ADVANCE_RECORD_3:
        CALL FILE_SIZE_FROM_EXTENT
FCB_ADVANCE_RECORD_4:
        CALL FCB_PRIME_FIELDS
        XOR A
        JP BDOS_RET_RESULT
FCB_ADVANCE_RECORD_5:
        CALL $DED4
        JP MARK_FCB_S2_HIGHBIT
; ----------------------------------------------------------------------
; FILE_WRITE_SEQ -- sequential-write entry into the shared read/deblock core (reached from BDOS_F_READ_SEQ).
;   In: current FCB at $DF11.
;   Out: enters FILE_READ_RECORD with the write-type flag set for a sequential operation.
;   Clobbers: A,B,C,D,E,H,L,flags.
;   Algorithm: set the write-type flag WRITE_TYPE=$BFE2 := 1 (sequential) then fall into FILE_READ_RECORD.
;   [RE] NOTE the dispatch is crossed in this 60K build: BDOS_F_READ_SEQ (fn 20) jumps here and this
;        entry feeds the read/deblock core. Twin of the 44K FILE_READ_SEQ (mode-flag set + fall-through).
; ----------------------------------------------------------------------
FILE_WRITE_SEQ:
        LD A,$01
        LD (WRITE_TYPE_FLAG),A
; ----------------------------------------------------------------------
; FILE_READ_RECORD -- read the FCB's current record into the DMA buffer (shared read core).
;   In: current FCB at $DF11; record/extent fields set. Shared by the sequential and random read paths.
;   Out: the record's sector read and de-blocked to the DMA address; result = 0/error via $DED0/$DED4.
;   Clobbers: A,B,C,D,E,H,L,flags.
;   Algorithm: set the direction flag $BFE0=$FF (read), FCB_PRIME_FIELDS, compare the working CR (FCB_CURREC)
;       against the extent's record count (FCB_RECCOUNT); at the $80 boundary advance to the next extent
;       (FCB_ADVANCE_RECORD), else REC_TO_BLOCK_14 / BLOCK_IS_ZERO_16 / BLOCK_BASE_RECORD_17 /
;       RECORD_TO_TRACK and read the sector (CALL $DF20).
;   [RE] CP/M 2.2 read core.
; ----------------------------------------------------------------------
FILE_READ_RECORD:
        LD A,$FF
        LD (RW_DIRECTION_FLAG),A
        CALL FCB_PRIME_FIELDS
        LD A,(FCB_CURREC)
        LD HL,FCB_RECCOUNT
        CP (HL)
        JR C,FILE_READ_RECORD_1
        CP $80
        JR NZ,FILE_READ_RECORD_2
        CALL FCB_ADVANCE_RECORD
        XOR A
        LD (FCB_CURREC),A
        LD A,(BDOS_RETVAL)
        OR A
        JR NZ,FILE_READ_RECORD_2
FILE_READ_RECORD_1:
        CALL REC_TO_BLOCK_14
        CALL BLOCK_IS_ZERO_16
        JR Z,FILE_READ_RECORD_2
        CALL BLOCK_BASE_RECORD_17
        CALL RECORD_TO_TRACK
        CALL $DF20
        JP FCB_WRITEBACK_REC
FILE_READ_RECORD_2:
        JP $DED4
; ----------------------------------------------------------------------
; FILE_READ_SEQ -- sequential-write entry into the shared write core (reached from BDOS_F_WRITE_SEQ).
;   In: current FCB at $DF11; DMA buffer holds the record.
;   Out: enters BDOS_WRITE with the write-type flag set for a sequential operation.
;   Clobbers: A,B,C,D,E,H,L,flags.
;   Algorithm: set the write-type flag WRITE_TYPE=$BFE2 := 1 (sequential) then fall into BDOS_WRITE.
;   [RE] NOTE the dispatch is crossed in this 60K build: BDOS_F_WRITE_SEQ (fn 21) jumps here and this
;        entry feeds the write core. Twin of the 44K FILE_WRITE_SEQ (mode-flag set + fall-through).
; ----------------------------------------------------------------------
FILE_READ_SEQ:
        LD A,$01
        LD (WRITE_TYPE_FLAG),A
; ----------------------------------------------------------------------
; BDOS_WRITE -- BDOS WRITE primitive (fn 21 F_WRITE / fn 34 F_WRITERAND / fn 40 F_WRITEZF target). Write
; the current record of the open file, allocating and deblocking disk blocks as needed.
;   In: current FCB at $DF11; the working record/record-count bytes primed by FCB_PRIME_FIELDS; DMA holds
;       the caller's record; WRITE_TYPE=$BFE2 = write type (1=sequential, 2=zero-fill/random); result
;       cell $DF13 = seek create/extend mode flag.
;   Out: A = BDOS return code (0=OK, 2=disk full) via the result cell $DF13 / $DED0; FCB allocation map /
;        record count updated; host sector written.  Clobbers: A,BC,DE,HL,flags.
;   Algorithm: clear the direction flag (RW_DIRECTION_FLAG); reject the record if the working CR (FCB_CURREC) >= 128
;       (extent full). REC_TO_BLOCK_14 / BLOCK_IS_ZERO_16: if the block is already allocated branch to
;       the write phase; else fetch the previous slot's block as a hint (FCB_BLOCKMAP_INDEX_10) and
;       ALLOC_GET_BLOCK a fresh block, store it into the FCB allocation slot (8- or 16-bit per $BFEA),
;       zero-fill new blocks when WRITE_TYPE=2, then RECORD_TO_TRACK and write (CALL $DF28), updating the
;       extent record count and CR via FCB_WRITEBACK_REC. Mirrors the standard CP/M 2.2 BDOS write. [RE]
; ----------------------------------------------------------------------
BDOS_WRITE:
        LD A,$00
        LD (RW_DIRECTION_FLAG),A
        CALL CHECK_DRIVE_READONLY
        LD HL,(BDOS_PARAM_PTR)
        CALL CHECK_DIRENT_READONLY_INNER
        CALL FCB_PRIME_FIELDS
        LD A,(FCB_CURREC)
        CP $80
        JP NC,$DED4
        CALL REC_TO_BLOCK_14
        CALL BLOCK_IS_ZERO_16
        LD C,$00
        JR NZ,BDOS_WRITE_PHASE
        CALL REC_BLOCK_SHIFT_6
        LD (ALLOC_SLOT_INDEX),A
        LD BC,$0000
        OR A
        JR Z,BDOS_WRITE_ALLOCBLK
        LD C,A
        DEC BC
        CALL FCB_BLOCKMAP_INDEX_10
        LD B,H
        LD C,L
BDOS_WRITE_ALLOCBLK:
        CALL ALLOC_GET_BLOCK
        LD A,L
        OR H
        JR NZ,BDOS_WRITE_STOREBLK
        LD A,$02
        JP BDOS_RET_RESULT
BDOS_WRITE_STOREBLK:
        LD (CUR_BLOCK_NUMBER),HL
        EX DE,HL
        LD HL,(BDOS_PARAM_PTR)
        LD BC,$0010
        ADD HL,BC
        LD A,(BLOCK_WIDTH_FLAG)
        OR A
        LD A,(ALLOC_SLOT_INDEX)
        JR Z,BDOS_WRITE_STOREBLK16
        CALL DIRENT_PTR_ADD
        LD (HL),E
        JR BDOS_WRITE_NEWBLK
BDOS_WRITE_STOREBLK16:
        LD C,A
        LD B,$00
        ADD HL,BC
        ADD HL,BC
        LD (HL),E
        INC HL
        LD (HL),D
BDOS_WRITE_NEWBLK:
        LD C,$02
BDOS_WRITE_PHASE:
        LD A,(BDOS_RETVAL)
        OR A
        RET NZ
        PUSH BC
        CALL BLOCK_BASE_RECORD_17
        LD A,(WRITE_TYPE_FLAG)
        DEC A
        DEC A
        JR NZ,BDOS_WRITE_DOWRITE
        POP BC
        PUSH BC
        LD A,C
        DEC A
        DEC A
        JR NZ,BDOS_WRITE_DOWRITE
        PUSH HL
        LD HL,(DIRBUF_PTR)
        LD D,A
BDOS_WRITE_ZEROFILL:
        LD (HL),A
        INC HL
        INC D
        JP P,BDOS_WRITE_ZEROFILL
        CALL SET_DMA_TO_DISK_BUF
        LD HL,(BLOCK_BASE_RECORD)
        LD C,$02
BDOS_WRITE_FILLLOOP:
        LD (CUR_BLOCK_NUMBER),HL
        PUSH BC
        CALL RECORD_TO_TRACK
        POP BC
        CALL $DF28
        LD HL,(CUR_BLOCK_NUMBER)
        LD C,$00
        LD A,(DPB_BLM)
        LD B,A
        AND L
        CP B
        INC HL
        JR NZ,BDOS_WRITE_FILLLOOP
        POP HL
        LD (CUR_BLOCK_NUMBER),HL
        CALL RESTORE_USER_DMA
BDOS_WRITE_DOWRITE:
        CALL RECORD_TO_TRACK
        POP BC
        PUSH BC
        CALL $DF28
        POP BC
        LD A,(FCB_CURREC)
        LD HL,FCB_RECCOUNT
        CP (HL)
        JR C,BDOS_WRITE_9
        LD (HL),A
        INC (HL)
        LD C,$02
BDOS_WRITE_9:
        PUSH AF
        CALL FCB_GET_S2
        AND $7F
        LD (HL),A
        POP AF
        CP $7F
        JR NZ,BDOS_WRITE_11
        LD A,(WRITE_TYPE_FLAG)
        CP $01
        JR NZ,BDOS_WRITE_11
        CALL FCB_WRITEBACK_REC
        CALL FCB_ADVANCE_RECORD
        LD HL,BDOS_RETVAL
        LD A,(HL)
        OR A
        JR NZ,BDOS_WRITE_10
        DEC A
        LD (FCB_CURREC),A
BDOS_WRITE_10:
        LD (HL),$00
BDOS_WRITE_11:
        JP FCB_WRITEBACK_REC
; ----------------------------------------------------------------------
; BDOS_SEEK_NOREAD -- SEEK entry that clears the write-type cell, then computes/positions the target extent.
;   In: current FCB at $DF11 valid.
;   Out: as for BDOS_SEEK_COMPUTE below.  Clobbers: A,BC,DE,HL,flags.
;   Algorithm: clear the write-type cell (WRITE_TYPE=$BFE2 := 0), then fall straight into BDOS_SEEK_COMPUTE.
;       (OBSERVED: used by the random read/write bodies after they set C; BDOS_SEEK_NOREAD itself does not
;       consume C -- it is merely preserved on the stack across the seek and used by the caller after.) [RE]
; ----------------------------------------------------------------------
BDOS_SEEK_NOREAD:
        XOR A
        LD (WRITE_TYPE_FLAG),A
; ----------------------------------------------------------------------
; BDOS_SEEK_COMPUTE -- compute the target extent/record from the FCB random-record field (R0/R1/R2) and seek the directory to it.
;   In: current FCB at $DF11 whose random-record bytes (FCB+$21..$23 = R0/R1/R2) hold the desired record;
;       result cell $DF13 = create/extend mode flag.
;   Out: B = target S2 (module), C = target extent-within-entry; if the FCB is already positioned there,
;        returns OK (A=0) via $DED0; else repositions the directory; on R2 != 0 returns record-out-of-range.
;        (OBSERVED: BC is also just preserved on the stack for the calling read/write routine.)
;   Clobbers: A,BC,DE,HL,flags.
;   Algorithm: read R0 and combine with R1 into the 16-bit record number. record-within-extent = R0 & $7F;
;       extent = ((R1<<1)|R0.bit7) & $1F (C); S2/module = R1>>4 (B). If R2 (high random byte) is non-zero
;       the record is out of range -> abort with phase code 6. Otherwise compare target extent (C vs
;       FCB+$0C) and S2 (B vs FCB+$0E): if both match, fall through with no positioning; else reposition
;       to the target extent. Mirrors the standard CP/M 2.2 BDOS random seek. [RE]
; ----------------------------------------------------------------------
BDOS_SEEK_COMPUTE:
        PUSH BC
        LD HL,(BDOS_PARAM_PTR)
        EX DE,HL
        LD HL,$0021
        ADD HL,DE
        LD A,(HL)
        AND $7F
        PUSH AF
        LD A,(HL)
        RLA
        INC HL
        LD A,(HL)
        RLA
        AND $1F
        LD C,A
        LD A,(HL)
        RRA
        RRA
        RRA
        RRA
        AND $0F
        LD B,A
        POP AF
        INC HL
        LD L,(HL)
        INC L
        DEC L
        LD L,$06
        JR NZ,RANDREC_POS_RET
        LD HL,$0020
        ADD HL,DE
        LD (HL),A
        LD HL,$000C
        ADD HL,DE
        LD A,C
        SUB (HL)
        JR NZ,BDOS_SEEK_REPOSITION
        LD HL,$000E
        ADD HL,DE
        LD A,B
        SUB (HL)
        AND $7F
        JR Z,BDOS_SEEK_DONE
BDOS_SEEK_REPOSITION:
        PUSH BC
        PUSH DE
        CALL F_CLOSE_HND
        POP DE
        POP BC
        LD L,$03
        LD A,(BDOS_RETVAL)
        INC A
        JR Z,BDOS_SEEK_COMPUTE_3
        LD HL,$000C
        ADD HL,DE
        LD (HL),C
        LD HL,$000E
        ADD HL,DE
        LD (HL),B
        CALL FILE_OPEN_SEARCH
        LD A,(BDOS_RETVAL)
        INC A
        JR NZ,BDOS_SEEK_DONE
        POP BC
        PUSH BC
        LD L,$04
        INC C
        JR Z,BDOS_SEEK_COMPUTE_3
        CALL DIR_MAKE_ENTRY
        LD L,$05
        LD A,(BDOS_RETVAL)
        INC A
        JR Z,BDOS_SEEK_COMPUTE_3
BDOS_SEEK_DONE:
        POP BC
        XOR A
        JP BDOS_RET_RESULT
BDOS_SEEK_COMPUTE_3:
        PUSH HL
        CALL FCB_GET_S2
        LD (HL),$C0
        POP HL
RANDREC_POS_RET:
        POP BC
        LD A,L
        LD (BDOS_RETVAL),A
        JP MARK_FCB_S2_HIGHBIT
; ----------------------------------------------------------------------
; F_READRAND_BODY -- BDOS function 33 (Read Random) worker: position the FCB from its random record, then read that record.
;   In: current FCB at $DF11 (random-record field r0/r1/r2 set by the caller); reached from BDOS_F_READRAND
;       after FCB_AUTO_DRIVE_SELECT.
;   Out: read result stored in the result cell (BDOS_RETVAL) by the called read routine; Z from positioning
;        governs whether the read runs.  Clobbers: A,BC,DE,HL.
;   Algorithm: C := $FF (read mode = do NOT extend the file); CALL BDOS_SEEK_NOREAD (BDOS_SEEK_COMPUTE) to
;       convert the random record into extent + current-record fields; if positioning succeeded (Z), CALL
;       FILE_READ_RECORD to read the addressed record; RET.
;   [RE][DOC CP/M 2.2 BDOS fn 33] C=$FF is consumed inside BDOS_SEEK_COMPUTE: a read past EOF fails instead
;       of allocating. The conditional CALL Z performs the sector read only when positioning succeeded.
; ----------------------------------------------------------------------
F_READRAND_BODY:
        LD C,$FF
        CALL BDOS_SEEK_NOREAD
        CALL Z,FILE_READ_RECORD
        RET
; ----------------------------------------------------------------------
; F_WRITERAND_BODY -- BDOS function 34 (Write Random) worker: position the FCB from its random record, then write that record.
;   In: current FCB at $DF11 (random-record field set by the caller); reached from BDOS_F_WRITERAND after
;       FCB_AUTO_DRIVE_SELECT; DMA holds the record.
;   Out: write result stored in the result cell (BDOS_RETVAL) by the called write routine; Z from positioning
;        governs whether the write runs.  Clobbers: A,BC,DE,HL.
;   Algorithm: C := $00 (write mode = allocate/extend as needed); CALL BDOS_SEEK_NOREAD (BDOS_SEEK_COMPUTE)
;       to set extent + current-record from the random record; if positioning succeeded (Z), CALL
;       BDOS_WRITE to write the record; RET.
;   [RE][DOC CP/M 2.2 BDOS fn 34] C=$00 is consumed inside BDOS_SEEK_COMPUTE: the extend path is taken
;       rather than the error tail, allowing a new extent/block to be allocated.
; ----------------------------------------------------------------------
F_WRITERAND_BODY:
        LD C,$00
        CALL BDOS_SEEK_NOREAD
        CALL Z,BDOS_WRITE
        RET
; ----------------------------------------------------------------------
; FCB_ALLOC_PREP -- compute the 24-bit absolute record number from an FCB's record byte plus its extent (EX) and S2 fields.
;   In: HL = base pointer to the FCB (or directory entry); DE = byte offset within it of the low record
;       byte to read (e.g. $20 = CR for Set Random Record, $0F for the per-extent record count in Compute File Size).
;   Out: C = low byte, B = mid byte, A = high byte of the record number; A AND $01 leaves Z/NZ on the
;        result's low bit for callers.  Clobbers: A,BC,HL,DE,flags.
;   Algorithm: EX DE,HL so HL=offset, DE=FCB base; ADD HL,DE -> &FCB+offset; C := that byte, B := 0. Read
;       the extent byte (offset $0C): RRCA then AND $80 folds its bit0 into bit7, add to C (carry into B)
;       -- the *128 contribution; RRCA/AND $0F of the extent byte adds the extent high nibble into B. Read
;       S2 (offset $0E): shift left 4, add into B; final AND $01 sets Z/NZ on the low bit.
;   [RE] builds the linear absolute record index (record + ex*128 + S2*...) used by Set Random Record (fn 36)
;       and Compute File Size (fn 35). Twin of the 44K FCB_ALLOC_PREP.
; ----------------------------------------------------------------------
FCB_ALLOC_PREP:
        EX DE,HL
        ADD HL,DE
        LD C,(HL)
        LD B,$00
        LD HL,$000C
        ADD HL,DE
        LD A,(HL)
        RRCA
        AND $80
        ADD A,C
        LD C,A
        LD A,$00
        ADC A,B
        LD B,A
        LD A,(HL)
        RRCA
        AND $0F
        ADD A,B
        LD B,A
        LD HL,$000E
        ADD HL,DE
        LD A,(HL)
        ADD A,A
        ADD A,A
        ADD A,A
        ADD A,A
        PUSH AF
        ADD A,B
        LD B,A
        PUSH AF
        POP HL
        LD A,L
        POP HL
        OR L
        AND $01
        RET
; ----------------------------------------------------------------------
; F_COMPSIZE_BODY -- BDOS function 35 (Compute File Size) worker: scan the directory and write the max record number into r0/r1/r2.
;   In: current FCB at $DF11; reached from BDOS_F_SIZE after FCB_AUTO_DRIVE_SELECT.
;   Out: FCB random-record bytes r0/r1/r2 (offsets $21-$23) set to the file's record count (one past the
;        highest record across all matching directory extents).  Clobbers: A,BC,DE,HL.
;   Algorithm: C := $0C, DIR_SEARCH_FIRST over the first 12 FCB bytes (drive+name+type; extent NOT matched);
;       point HL at FCB+$21 and zero the three random-record bytes. Loop over every matching entry: compute
;       its record number via FCB_ALLOC_PREP at offset $0F and keep the running maximum in r0/r1/r2;
;       when the search exhausts, the largest record number remains stored.
;   [RE][DOC CP/M 2.2 BDOS fn 35] result is a record count (next free record), one past the highest used record.
; ----------------------------------------------------------------------
F_COMPSIZE_BODY:
        LD C,$0C
        CALL DIR_SEARCH_FIRST
        LD HL,(BDOS_PARAM_PTR)
        LD DE,$0021
        ADD HL,DE
        PUSH HL
        LD (HL),D
        INC HL
        LD (HL),D
        INC HL
        LD (HL),D
COMPSIZE_SCAN_LOOP:
        CALL CUR_RECORD_BYTES_EQUAL
        JR Z,FCB_RECNUM_FROM_FIELDS_4
        CALL FCB_BUF_PTR_ADD_OFFSET
        LD DE,$000F
        CALL FCB_ALLOC_PREP
        POP HL
        PUSH HL
        LD E,A
        LD A,C
        SUB (HL)
        INC HL
        LD A,B
        SBC A,(HL)
        INC HL
        LD A,E
        SBC A,(HL)
        JR C,COMPSIZE_NEXT
        LD (HL),E
        DEC HL
        LD (HL),B
        DEC HL
        LD (HL),C
COMPSIZE_NEXT:
        CALL BDOS_DIR_SCAN_NEXT
        JR COMPSIZE_SCAN_LOOP
FCB_RECNUM_FROM_FIELDS_4:
        POP HL
        RET
; ----------------------------------------------------------------------
; BDOS_F_RANDREC -- BDOS function 36 (Set Random Record): compute the random-record field of the current FCB from its sequential position.
;   In: current FCB at $DF11 (whose sequential extent/CR fields are to be converted).
;   Out: bytes r0/r1/r2 (FCB offsets $21..$23) written with the 24-bit record number derived from the FCB's
;        extent and current-record fields.  Clobbers: A,BC,DE,HL.
;   Algorithm: RANDREC_FIELD_RESET stages the FCB into the scratch, then FCB_ALLOC_PREP with HL=FCB
;       base and DE=$0020 folds the CR (FCB+$20), extent number and extent-high bit into a record count in
;       C(low)/B(high)/A(overflow); then HL = FCB+$0021 and store C,B,A into FCB[$21],[$22],[$23].
;   [RE] dispatch fn 36 ($DC9B->$BE31); FCB_ALLOC_PREP is the standard extent->record-count fold.
; ----------------------------------------------------------------------
BDOS_F_RANDREC:
        CALL RANDREC_FIELD_RESET
        LD HL,(BDOS_PARAM_PTR)
        LD DE,$0020
        CALL FCB_ALLOC_PREP
        LD HL,$0021
        ADD HL,DE
        LD (HL),C
        INC HL
        LD (HL),B
        INC HL
        LD (HL),A
        RET
; ----------------------------------------------------------------------
; BDOS_F_SELDSK -- BDOS function 14 (Select Disk): make the drive in the select arg (DRV_SELECT_ARG) the current drive.
;   In: requested drive at $BFE3; current drive at $DF10.
;   Out: if the drive changed, $DF10 is updated and the drive is logged in / allocation vector rebuilt (via
;        DRV_LOGIN_SCAN); otherwise no-op.  Clobbers: A,HL (and whatever DRV_LOGIN_SCAN clobbers).
;   Algorithm: compare desired drive (DRV_SELECT_ARG) with current (BDOS_CUR_DRIVE); if equal return; else store the new
;       current drive and fall into DRV_LOGIN_SCAN, the select/log-in worker.
;   [RE] dispatch fn 14 ($DC6F->$BE47); matches canonical CP/M 2.2 Select Disk.
; ----------------------------------------------------------------------
BDOS_F_SELDSK:
        LD A,(DRV_SELECT_ARG)
        LD HL,BDOS_CUR_DRIVE
        CP (HL)
        RET Z
        LD (HL),A
; ----------------------------------------------------------------------
; DRV_LOGIN_SCAN -- Select-disk / log-in worker: ensure the current drive is logged in, and rebuild its allocation vector if it was not.
;   In: current drive at $DF10; the working login/select vector DRV_SELECT_VECTOR at $BFBC.
;   Out: if the drive was newly logged in, its DPB is fetched (SELDSK_DPB_FETCH) and its allocation vector
;        rebuilt (ALLOC_VECTOR_BUILD); DRV_SELECT_VECTOR updated with the drive's login bit.  Clobbers: A,BC,DE,HL.
;   Algorithm: load the working login vector (DRV_SELECT_VECTOR); build a single-bit mask for the current drive
;       (SHR_HL_C); test (SELDSK_DPB_FETCH) whether the drive's DPB is already established; if not yet
;       logged in (Z) call $DF15 to log it in / scan its directory; if the login bit was already set (RRA
;       -> carry) just return; otherwise OR this drive's bit into DRV_SELECT_VECTOR, store it, and fall
;       into ALLOC_VECTOR_BUILD.
;   [RE] the standard CP/M 2.2 select-disk login path reached from BDOS_F_SELDSK (fn 14) and BDOS_F_DSKRESET
;       (fn 13). Twin of the 44K DRV_INSTALL_RWTS_17. [?] the RRA already-logged-in test is inferred.
; ----------------------------------------------------------------------
DRV_LOGIN_SCAN:
        LD HL,(DRV_SELECT_VECTOR)
        LD A,(BDOS_CUR_DRIVE)
        LD C,A
        CALL SHR_HL_C
        PUSH HL
        EX DE,HL
        CALL SELDSK_DPB_FETCH
        POP HL
        CALL Z,$DF15
        LD A,L
        RRA
        RET C
        LD HL,(DRV_SELECT_VECTOR)
        LD C,L
        LD B,H
        CALL DRIVE_BIT_OR_INTO_VECTOR
        LD (DRV_SELECT_VECTOR),HL
        JP ALLOC_VECTOR_BUILD
; ----------------------------------------------------------------------
; FCB_AUTO_DRIVE_SELECT -- common file-operation preamble: reset the random scratch then honor the drive prefix in the caller's FCB.
;   In: current FCB at $DF11 (byte 0 = drive prefix, 0=default else drive+1); current drive $DF10; current user $DF0F.
;   Out: RANDREC_FIELD_RESET stages the FCB into the scratch; then FCB_LOGIN_SELECT: if the FCB names an
;        explicit drive, that drive is selected (BDOS_F_SELDSK) and the prior drive/FCB-byte saved; the
;        FCB's drive byte is rewritten to OR in the current user number.  Clobbers: A,BC,DE,HL.
;   Algorithm: CALL RANDREC_FIELD_RESET, then fall into FCB_LOGIN_SELECT.
;   [RE] the auto-disk-select / FCB drive-prefix handler that nearly every file BDOS call funnels through.
; ----------------------------------------------------------------------
FCB_AUTO_DRIVE_SELECT:
        CALL RANDREC_FIELD_RESET
; ----------------------------------------------------------------------
; FCB_LOGIN_SELECT -- honor the drive prefix in the current FCB, temporarily selecting that drive.
;   In: current FCB at $DF11 (byte 0 = drive prefix); current drive $DF10; current user $DF0F.
;   Out: if the FCB names an explicit drive, that drive is selected (select-arg $BFE3 set, BDOS_F_SELDSK
;        called) and the prior drive is saved in the restore cells ($BFEB flag=$FF, $BFEC=saved drive,
;        $BFED=saved FCB drive byte); the FCB's drive byte is OR'd with the current user number.  Clobbers: A,BC,DE,HL.
;   Algorithm: set restore-pending flag $BFEB=$FF; read FCB byte0, mask $1F and DEC to get drive index into
;       $BFE3; if >=$1E (no explicit drive) skip the switch (FCB_MERGE_USER); else save current drive
;       ($DF10->$BFEC) and original FCB byte (->$BFED), strip the prefix bits ($E0 mask) from FCB byte0,
;       select the requested drive (BDOS_F_SELDSK); finally OR the current user number (BDOS_STACK_TOP) into FCB byte0.
;   [RE] the FCB drive-prefix handler; the matching restore is done on the BDOS bank-out epilogue. Twin of
;       the 44K FCB_AUTO_DRIVE_SELECT body.
; ----------------------------------------------------------------------
FCB_LOGIN_SELECT:
        LD A,$FF
        LD (DRV_RESTORE_FLAG),A
        LD HL,(BDOS_PARAM_PTR)
        LD A,(HL)
        AND $1F
        DEC A
        LD (DRV_SELECT_ARG),A
        CP $1E
        JR NC,FCB_MERGE_USER
        LD A,(BDOS_CUR_DRIVE)
        LD (DRV_SAVED_DRIVE),A
        LD A,(HL)
        LD (DRV_SAVED_FCB_BYTE),A
        AND $E0
        LD (HL),A
        CALL BDOS_F_SELDSK
; ----------------------------------------------------------------------
; FCB_MERGE_USER -- tail of FCB_LOGIN_SELECT: OR the current user number into the FCB's drive byte.
;   In: current user number at $DF0F; current FCB at $DF11.
;   Out: FCB byte0 |= current user number.  Clobbers: A,HL.
;   Algorithm: load user number (BDOS_STACK_TOP), OR with FCB byte0, store back.
;   [RE] shared exit of the auto-disk-select preamble.
; ----------------------------------------------------------------------
FCB_MERGE_USER:
        LD A,(BDOS_STACK_TOP)
        LD HL,(BDOS_PARAM_PTR)
        OR (HL)
        LD (HL),A
        RET
; ----------------------------------------------------------------------
; BDOS_F_VERSION -- BDOS function 12 (Return Version Number): report CP/M 2.2.
;   In: none.  Out: low byte of the BDOS result (BDOS_RETVAL) set to $22 (= version 2.2) via $DED0.  Clobbers: A.
;   Algorithm: load $22 and store it as the low byte of the BDOS return result.
;   [RE] dispatch fn 12 ($DC6B->$BEA3); $22 = CP/M 2.2 per the canonical version code.
; ----------------------------------------------------------------------
BDOS_F_VERSION:
        LD A,$22
        JP BDOS_RET_RESULT
; ----------------------------------------------------------------------
; BDOS_F_DSKRESET -- BDOS function 13 (Reset Disk System): return CP/M to its initial disk state.
;   In: none.  Out: login vector (DRV_LOGIN_VECTOR $BFBA) and working login/select vector
;       (DRV_SELECT_VECTOR $BFBC) cleared; current drive $DF10 forced to A: (0); DMA address (DMA_ADDR) reset
;       to TBUFF ($0080); drive A logged in fresh.  Clobbers: A,HL (and DRV_LOGIN_SCAN / RESTORE_USER_DMA clobbers).
;   Algorithm: zero $BFBA and $BFBC; set current drive $DF10=0; set DMA_ADDR $BFBE=$0080 (TBUFF); CALL
;       RESTORE_USER_DMA (apply to the live BIOS DMA); JR DRV_LOGIN_SCAN to log in drive A.
;   [RE] dispatch fn 13 ($DC6D->$BEA8); matches canonical CP/M 2.2 Reset Disk System.
; ----------------------------------------------------------------------
BDOS_F_DSKRESET:
        LD HL,$0000
        LD (DRV_LOGIN_VECTOR),HL
        LD (DRV_SELECT_VECTOR),HL
        XOR A
        LD (BDOS_CUR_DRIVE),A
        LD HL,$0080
        LD (DMA_ADDR),HL
        CALL RESTORE_USER_DMA
        JR DRV_LOGIN_SCAN
; ----------------------------------------------------------------------
; BDOS_F_OPEN -- BDOS function 15 (Open File): open the file named by the FCB.
;   In: current FCB at $DF11.
;   Out: directory match result via FILE_OPEN_SEARCH; FCB filled in from the matching directory entry on
;        success, $FF if not found.  Clobbers: A,BC,DE,HL.
;   Algorithm: F_MAKE_OPEN_PREP (reset random scratch, clear S2, log in the FCB drive); JP FILE_OPEN_SEARCH.
;   [RE] dispatch fn 15 ($DC71->$BEC0); canonical CP/M 2.2 Open File.
; ----------------------------------------------------------------------
BDOS_F_OPEN:
        CALL F_MAKE_OPEN_PREP
        JP FILE_OPEN_SEARCH
; ----------------------------------------------------------------------
; BDOS_F_CLOSE -- BDOS function 16 (Close File): write the FCB back to its directory entry.
;   In: current FCB at $DF11 (must be open).
;   Out: directory entry updated; result via the F_CLOSE_HND path ($FF / dir-code).  Clobbers: A,BC,DE,HL.
;   Algorithm: FCB_AUTO_DRIVE_SELECT honors the FCB drive prefix; JP into F_CLOSE_HND.
;   [RE] dispatch fn 16 ($DC73->$BEC6); canonical CP/M 2.2 Close File.
; ----------------------------------------------------------------------
BDOS_F_CLOSE:
        CALL FCB_AUTO_DRIVE_SELECT
        JP F_CLOSE_HND
; ----------------------------------------------------------------------
; BDOS_F_SFIRST -- BDOS function 17 (Search for First): find the first directory entry matching the FCB.
;   In: current FCB at $DF11 (staged from DE). FCB byte0 = $3F ('?') means 'match every entry'.
;   Out: directory match copied to the DMA buffer; result (0..3 = dir position, or $FF none) via SET_DMA_TO_DISK_BUF_2.
;   Clobbers: A,BC,DE,HL.
;   Algorithm: RANDREC_FIELD_RESET; C=0 (default match length); fetch FCB byte0; if byte0==$3F do an
;       unqualified all-entries scan; else test the extent byte FCB[$0C] -- if not '?' CLEAR_FCB_S2 -- then
;       FCB_LOGIN_SELECT and C=$0F (15-byte name+type+extent match); fall into DIR_SEARCH_AND_COPY.
;   [RE] dispatch fn 17 ($DC75->$BECC); canonical CP/M 2.2 Search First; $3F is the '?' all-match marker.
; ----------------------------------------------------------------------
BDOS_F_SFIRST:
        CALL RANDREC_FIELD_RESET
        LD C,$00
        EX DE,HL
        LD A,(HL)
        CP $3F
        JR Z,DIR_SEARCH_AND_COPY
        CALL FCB_PTR_EXTENT
        LD A,(HL)
        CP $3F
SFIRST_CLR_S2:
        CALL NZ,CLEAR_FCB_S2
        CALL FCB_LOGIN_SELECT
        LD C,$0F
; ----------------------------------------------------------------------
; DIR_SEARCH_AND_COPY -- run the directory scan and copy the matched entry to the DMA buffer.
;   In: C = number of bytes to compare; search FCB already established by BDOS_F_SFIRST.
;   Out: matching directory record moved to the DMA buffer; A = directory position (0..3) or $FF if none.
;   Clobbers: A,BC,DE,HL.
;   Algorithm: DIR_SEARCH_FIRST performs the directory search with the C-byte mask; JP SET_DMA_TO_DISK_BUF_2 (the
;       disk-buffer -> user-DMA copy) to deliver the located entry and return the result code.
;   [RE] shared search tail for fn 17 (Search First) and fn 18 (Search Next).
; ----------------------------------------------------------------------
DIR_SEARCH_AND_COPY:
        CALL DIR_SEARCH_FIRST
        JP SET_DMA_TO_DISK_BUF_2
; ----------------------------------------------------------------------
; BDOS_F_SNEXT -- BDOS function 18 (Search for Next): continue a directory search begun by Search First.
;   In: the saved search FCB pointer at $DF85 (stored by RANDREC_FIELD_RESET during Search First).
;   Out: next matching directory record copied to the DMA buffer; A = position (0..3) or $FF if no more.
;   Clobbers: A,BC,DE,HL.
;   Algorithm: restore the saved search FCB pointer ($DF85 -> DE); RANDREC_FIELD_RESET; FCB_LOGIN_SELECT;
;       BDOS_DIR_SCAN_NEXT advances the scan from the saved position; JP SET_DMA_TO_DISK_BUF_2 to deliver the hit.
;   [RE] dispatch fn 18 ($DC77->$BEEB); canonical CP/M 2.2 Search Next.
; ----------------------------------------------------------------------
BDOS_F_SNEXT:
        LD DE,(DEFERRED_COPY_DST)
        CALL RANDREC_FIELD_RESET
        EX DE,HL
        CALL FCB_LOGIN_SELECT
        CALL BDOS_DIR_SCAN_NEXT
        JP SET_DMA_TO_DISK_BUF_2
; ----------------------------------------------------------------------
; BDOS_F_DELETE -- BDOS function 19 (Delete File): erase all directory entries matching the FCB.
;   In: current FCB at $DF11 (possibly ambiguous).
;   Out: matching directory entries marked deleted ($E5) and their allocation freed; result via
;        DIR_RETURN_MATCH_FLAG ($FF if none / dir code).  Clobbers: A,BC,DE,HL.
;   Algorithm: FCB_AUTO_DRIVE_SELECT honors the drive prefix; F_DELETE_HND scans and erases each matching
;       entry (releasing its blocks); JP DIR_RETURN_MATCH_FLAG.
;   [RE] dispatch fn 19 ($DC79->$BEFC); canonical CP/M 2.2 Delete File.
; ----------------------------------------------------------------------
BDOS_F_DELETE:
        CALL FCB_AUTO_DRIVE_SELECT
        CALL F_DELETE_HND
        JP DIR_RETURN_MATCH_FLAG
; ----------------------------------------------------------------------
; BDOS_F_READ_SEQ -- BDOS function 20 (Read Sequential): read the next 128-byte record of the open file.
;   In: current FCB at $DF11 positioned at the next sequential record.
;   Out: one record read into the DMA buffer; A = 0 on success or a nonzero read-error/EOF code; FCB
;        position advanced.  Clobbers: A,BC,DE,HL.
;   Algorithm: FCB_AUTO_DRIVE_SELECT honors the drive prefix; JP FILE_WRITE_SEQ (the sequential entry into
;       the shared read core; the FILE_WRITE_SEQ/FILE_READ_SEQ labels are cross-wired in this 60K build).
;   [RE] dispatch fn 20 ($DC7B->$BF05); canonical CP/M 2.2 Read Sequential.
; ----------------------------------------------------------------------
BDOS_F_READ_SEQ:
        CALL FCB_AUTO_DRIVE_SELECT
        JP FILE_WRITE_SEQ
; ----------------------------------------------------------------------
; BDOS_F_WRITE_SEQ -- BDOS function 21 (Write Sequential): write the next 128-byte record to the open file.
;   In: current FCB at $DF11; DMA buffer holds the record to write.
;   Out: one record written; A = 0 on success or a nonzero error code (disk full / R/O); FCB position
;        advanced, allocation extended as needed.  Clobbers: A,BC,DE,HL.
;   Algorithm: FCB_AUTO_DRIVE_SELECT honors the drive prefix; JP FILE_READ_SEQ (the sequential entry into
;       the shared write core; the FILE_READ_SEQ/FILE_WRITE_SEQ labels are cross-wired in this 60K build).
;   [RE] dispatch fn 21 ($DC7D->$BF0B); canonical CP/M 2.2 Write Sequential.
; ----------------------------------------------------------------------
BDOS_F_WRITE_SEQ:
        CALL FCB_AUTO_DRIVE_SELECT
        JP FILE_READ_SEQ
; ----------------------------------------------------------------------
; BDOS_F_MAKE -- BDOS function 22 (Make File): create a new directory entry for the FCB.
;   In: current FCB at $DF11 naming the file to create.
;   Out: a fresh, empty directory entry allocated and the FCB opened against it; A = dir position or $FF if
;        the directory is full.  Clobbers: A,BC,DE,HL.
;   Algorithm: F_MAKE_OPEN_PREP (reset random scratch, clear S2, log in the FCB drive); JP DIR_MAKE_ENTRY.
;   [RE] dispatch fn 22 ($DC7F->$BF11); canonical CP/M 2.2 Make File.
; ----------------------------------------------------------------------
BDOS_F_MAKE:
        CALL F_MAKE_OPEN_PREP
        JP DIR_MAKE_ENTRY
; ----------------------------------------------------------------------
; BDOS_F_RENAME -- BDOS function 23 (Rename File): change a file's name in its directory entries.
;   In: current FCB at $DF11 whose first 12 bytes hold the old name and bytes $10.. the new name.
;   Out: every matching directory entry's name field rewritten to the new name; result via DIR_RETURN_MATCH_FLAG.
;   Clobbers: A,BC,DE,HL.
;   Algorithm: FCB_AUTO_DRIVE_SELECT honors the drive prefix; F_RENAME_HND rewrites matched entries; JP
;       DIR_RETURN_MATCH_FLAG.
;   [RE] dispatch fn 23 ($DC81->$BF17); canonical CP/M 2.2 Rename File.
; ----------------------------------------------------------------------
BDOS_F_RENAME:
        CALL FCB_AUTO_DRIVE_SELECT
        CALL F_RENAME_HND
        JP DIR_RETURN_MATCH_FLAG
; ----------------------------------------------------------------------
; BDOS_F_LOGINVEC -- BDOS function 24 (Return Login Vector): report which drives are logged in.
;   In: DRV_SELECT_VECTOR (DRV_SELECT_VECTOR) = working login/select vector (bit d = drive d logged in).
;   Out: BDOS result HL = the login vector (returned via BDOS_RET_RESULT_HL, result cell $DF13).  Clobbers: HL.
;   Algorithm: load the working login vector (DRV_SELECT_VECTOR) and store it as the 16-bit BDOS result.
;   [RE] dispatch fn 24 ($DC83->$BF20); canonical CP/M 2.2 Return Login Vector.
; ----------------------------------------------------------------------
BDOS_F_LOGINVEC:
        LD HL,(DRV_SELECT_VECTOR)
        JR BDOS_RET_RESULT_HL
; ----------------------------------------------------------------------
; BDOS_F_CURDSK -- BDOS function 25 (Return Current Disk): report the current default drive.
;   In: current drive at $DF10.  Out: BDOS result A = current drive (0=A:) via $DED0.  Clobbers: A.
;   Algorithm: load the current-drive cell (BDOS_CUR_DRIVE) and return it as the BDOS result.
;   [RE] dispatch fn 25 ($DC85->$BF25); canonical CP/M 2.2 Return Current Disk.
; ----------------------------------------------------------------------
BDOS_F_CURDSK:
        LD A,(BDOS_CUR_DRIVE)
        JP BDOS_RET_RESULT
; ----------------------------------------------------------------------
; BDOS_F_SETDMA -- BDOS function 26 (Set DMA Address): set the disk read/write buffer address.
;   In: DE = new DMA (disk transfer) address supplied by the caller.
;   Out: DMA_ADDR (DMA_ADDR) set to DE and pushed through to the BIOS disk-buffering layer.  Clobbers: A,HL
;        (and RESTORE_USER_DMA clobbers).
;   Algorithm: move DE into HL, store at DMA_ADDR (DMA_ADDR), JP RESTORE_USER_DMA to apply it to the live BIOS SETDMA.
;   [RE] dispatch fn 26 ($DC87->$BF2B); canonical CP/M 2.2 Set DMA Address.
; ----------------------------------------------------------------------
BDOS_F_SETDMA:
        EX DE,HL
        LD (DMA_ADDR),HL
        JP RESTORE_USER_DMA
; ----------------------------------------------------------------------
; BDOS_F_ALLOCVEC -- BDOS function 27 (Return Allocation Vector address).
;   In: the allocation (block-in-use) bit-vector base pointer at (ALLOC_VEC_PTR).
;   Out: BDOS result HL = the allocation vector address (via BDOS_RET_RESULT_HL).  Clobbers: HL.
;   Algorithm: load the allocation-vector pointer (ALLOC_VEC_PTR) and store it as the 16-bit BDOS result.
;   [RE] dispatch fn 27 ($DC89->$BF32); canonical CP/M 2.2 Get Allocation Vector.
; ----------------------------------------------------------------------
BDOS_F_ALLOCVEC:
        LD HL,(ALLOC_VEC_PTR)
        JR BDOS_RET_RESULT_HL
; ----------------------------------------------------------------------
; BDOS_F_ROVEC -- BDOS function 29 (Return Read-Only Vector): report which drives are read-only.
;   In: DRV_LOGIN_VECTOR (DRV_LOGIN_VECTOR) -- here read as the read-only bit vector master copy.
;   Out: BDOS result HL = the read-only drive vector (bit d set = drive d is R/O) via BDOS_RET_RESULT_HL.  Clobbers: HL.
;   Algorithm: load the R/O vector (DRV_LOGIN_VECTOR) and store it as the 16-bit BDOS result.
;   [RE] dispatch fn 29 ($DC8D->$BF37); canonical CP/M 2.2 Get Read-Only Vector. [?] the cell is named
;       DRV_LOGIN_VECTOR but holds the R/O bits in this build.
; ----------------------------------------------------------------------
BDOS_F_ROVEC:
        LD HL,(DRV_LOGIN_VECTOR)
        JR BDOS_RET_RESULT_HL
; ----------------------------------------------------------------------
; BDOS_F_ATTRIB -- BDOS function 30 (Set File Attributes): write the FCB's attribute bits into its directory entries.
;   In: current FCB at $DF11 carrying the desired attribute (high) bits in its name/type bytes.
;   Out: matching directory entries updated with the new attributes; result via DIR_RETURN_MATCH_FLAG.  Clobbers: A,BC,DE,HL.
;   Algorithm: FCB_AUTO_DRIVE_SELECT honors the drive prefix; F_ATTRIB_HND copies the attribute bits into
;       each matched entry; JP DIR_RETURN_MATCH_FLAG.
;   [RE] dispatch fn 30 ($DC8F->$BF3C); canonical CP/M 2.2 Set File Attributes.
; ----------------------------------------------------------------------
BDOS_F_ATTRIB:
        CALL FCB_AUTO_DRIVE_SELECT
        CALL F_ATTRIB_HND
        JP DIR_RETURN_MATCH_FLAG
; ----------------------------------------------------------------------
; BDOS_F_GETDPB -- BDOS function 31 (Return Disk Parameter Block address).
;   In: the current drive's DPB pointer at (DPB_PTR) (set during disk select/log-in).
;   Out: BDOS result HL = the DPB address (falls into the shared result-store BDOS_RET_RESULT_HL).  Clobbers: HL.
;   Algorithm: load the DPB pointer (DPB_PTR) and store it as the 16-bit BDOS result.
;   [RE] dispatch fn 31 ($DC91->$BF45); canonical CP/M 2.2 Get DPB.
; ----------------------------------------------------------------------
BDOS_F_GETDPB:
        LD HL,(DPB_PTR)
; ----------------------------------------------------------------------
; BDOS_RET_RESULT_HL -- common exit: store the 16-bit value in HL as the BDOS return result.
;   In: HL = value to return to the caller.
;   Out: BDOS result cell ($DF13, in the BDOS upper bank) = HL.  Clobbers: none (writes memory).
;   Algorithm: store HL at the BDOS result cell (BDOS_RETVAL) and return.
;   [RE] the HL-valued counterpart of the byte-result store; used by the get-vector / get-pointer
;       functions (login vector, alloc vector, R/O vector, DPB) and fallen into from BDOS_F_GETDPB.
; ----------------------------------------------------------------------
BDOS_RET_RESULT_HL:
        LD (BDOS_RETVAL),HL
        RET
; ----------------------------------------------------------------------
; BDOS_F_USERNUM -- BDOS function 32 (Get/Set User Code).
;   In: the caller's argument in $BFE3 ($FF = 'get', else the user number to set); current user at $DF0F.
;   Out: if get: BDOS result A = current user number (via $DED0); if set: current user $DF0F updated to (arg AND $1F).  Clobbers: A.
;   Algorithm: if the argument (DRV_SELECT_ARG) is $FF, return the current user number (BDOS_STACK_TOP); otherwise fall into
;       SET_USER_NUMBER to mask the argument to 0..31 and store it.
;   [RE] dispatch fn 32 ($DC93->$BF4C); canonical CP/M 2.2 Get/Set User; $FF = query.
; ----------------------------------------------------------------------
BDOS_F_USERNUM:
        LD A,(DRV_SELECT_ARG)
        CP $FF
        JR NZ,SET_USER_NUMBER
        LD A,(BDOS_STACK_TOP)
        JP BDOS_RET_RESULT
; ----------------------------------------------------------------------
; SET_USER_NUMBER -- set path of BDOS function 32: change the current user number.
;   In: A = requested user number.  Out: current user number $DF0F = A AND $1F (0..31).  Clobbers: A.
;   Algorithm: mask the requested user number to 5 bits and store it at $DF0F.
;   [RE] continuation of BDOS_F_USERNUM (Get/Set User).
; ----------------------------------------------------------------------
SET_USER_NUMBER:
        AND $1F
        LD (BDOS_STACK_TOP),A
        RET
; ----------------------------------------------------------------------
; BDOS_F_READRAND -- BDOS function 33 (Read Random): read the record addressed by the FCB's random-record field.
;   In: current FCB at $DF11 whose r0/r1/r2 ($21..$23) hold the target record number.
;   Out: that record read into the DMA buffer; A = 0 on success or a random-read error code (e.g. 1=reading
;        unwritten data, 6=record number out of range); FCB positioned at that record.  Clobbers: A,BC,DE,HL.
;   Algorithm: FCB_AUTO_DRIVE_SELECT honors the drive prefix; JP F_READRAND_BODY (seek to the random record and read it).
;   [RE] dispatch fn 33 ($DC95->$BF5F); canonical CP/M 2.2 Read Random.
; ----------------------------------------------------------------------
BDOS_F_READRAND:
        CALL FCB_AUTO_DRIVE_SELECT
        JP F_READRAND_BODY
; ----------------------------------------------------------------------
; BDOS_F_WRITERAND -- BDOS function 34 (Write Random): write the record addressed by the FCB's random-record field.
;   In: current FCB at $DF11 whose r0/r1/r2 hold the target record number; DMA buffer holds the record.
;   Out: that record written; A = 0 on success or a random-write error code; file extended/allocated as needed.  Clobbers: A,BC,DE,HL.
;   Algorithm: FCB_AUTO_DRIVE_SELECT honors the drive prefix; JP F_WRITERAND_BODY.
;   [RE] dispatch fn 34 ($DC97->$BF65); canonical CP/M 2.2 Write Random.
; ----------------------------------------------------------------------
BDOS_F_WRITERAND:
        CALL FCB_AUTO_DRIVE_SELECT
        JP F_WRITERAND_BODY
; ----------------------------------------------------------------------
; BDOS_F_SIZE -- BDOS function 35 (Compute File Size): set the FCB's random-record field to the file's record count.
;   In: current FCB at $DF11 naming the file.
;   Out: FCB r0/r1/r2 ($21..$23) set to the number of 128-byte records in the file (its 'virtual size').  Clobbers: A,BC,DE,HL.
;   Algorithm: FCB_AUTO_DRIVE_SELECT honors the drive prefix; JP F_COMPSIZE_BODY (scans the directory
;       extents for the highest record and writes it into the FCB random-record field).
;   [RE] dispatch fn 35 ($DC99->$BF6B); canonical CP/M 2.2 Compute File Size.
; ----------------------------------------------------------------------
BDOS_F_SIZE:
        CALL FCB_AUTO_DRIVE_SELECT
        JP F_COMPSIZE_BODY
; ----------------------------------------------------------------------
; BDOS_F_RESET_DRIVE -- BDOS function 37 (Reset Drive): mark the drives named by the caller's bit mask as no longer logged in.
;   In: the caller's reset bit-mask staged at $DF11 (one bit per drive to reset); DRV_SELECT_VECTOR (DRV_SELECT_VECTOR)
;       = working login vector; DRV_LOGIN_VECTOR (DRV_LOGIN_VECTOR) = master logged-in / R-O master vector.
;   Out: for each drive bit set in the mask, that drive's bit is cleared in both DRV_SELECT_VECTOR and
;        DRV_LOGIN_VECTOR, forcing a fresh log-in on next access.  Clobbers: A,DE,HL.
;   Algorithm: form the bitwise complement of the caller's reset mask (BDOS_PARAM_PTR); AND it into DRV_SELECT_VECTOR
;       (DRV_SELECT_VECTOR) to clear those login bits and store back; then AND the masked login word with
;       DRV_LOGIN_VECTOR (DRV_LOGIN_VECTOR) and store back.
;   [RE] dispatch fn 37 ($DC9D->$BF71); canonical CP/M 2.2 Reset Drive (selective reset).
; ----------------------------------------------------------------------
BDOS_F_RESET_DRIVE:
        LD HL,(BDOS_PARAM_PTR)
        LD A,L
        CPL
        LD E,A
        LD A,H
        CPL
        LD HL,(DRV_SELECT_VECTOR)
        AND H
        LD D,A
        LD A,L
        AND E
        LD E,A
        LD HL,(DRV_LOGIN_VECTOR)
        EX DE,HL
        LD (DRV_SELECT_VECTOR),HL
        LD A,L
        AND E
        LD L,A
        LD A,H
        AND D
        LD H,A
        LD (DRV_LOGIN_VECTOR),HL
        RET
; ----------------------------------------------------------------------
; BDOS_F_WRITEZF -- BDOS function 40 (Write Random with Zero Fill): like Write Random, but newly allocated blocks are pre-filled with zeros.
;   In: current FCB at $DF11 whose r0/r1/r2 hold the target record number; DMA buffer holds the record.
;   Out: the record written at the random position; any block newly allocated to reach it is zero-filled
;        first; A = 0 or a random-write error code.  Clobbers: A,BC,DE,HL.
;   Algorithm: FCB_AUTO_DRIVE_SELECT honors the drive prefix; set write-type WRITE_TYPE=$BFE2 := 2
;       (zero-fill); C=0; CALL BDOS_SEEK_COMPUTE and, on success (Z), CALL BDOS_WRITE.
;   [RE] dispatch fn 40 ($DCA3->$BF92); canonical CP/M 2.2 Write Random with Zero Fill; WRITE_TYPE=2
;       distinguishes it from normal Write Random.
; ----------------------------------------------------------------------
BDOS_F_WRITEZF:
        CALL FCB_AUTO_DRIVE_SELECT
        LD A,$02
        LD (WRITE_TYPE_FLAG),A
        LD C,$00
        CALL BDOS_SEEK_COMPUTE
        CALL Z,BDOS_WRITE
        RET
; ----------------------------------------------------------------------
; RANDREC_FIELD_RESET -- stage the caller's FCB into the BDOS scratch FCB and record it as the current/search FCB.
;   In: the caller's FCB pointer (in HL/DE at the call site); the scratch region at $DF87..
;   Out: current-FCB pointer $DF11 and saved-search-FCB pointer $DF85 both set to the scratch FCB copy at
;        $DF88; a 36-byte ($24) FCB image staged there via the lower-LC copy trampoline ($DF3C); DE = $DF88.
;   Clobbers: A,BC,DE,HL.
;   Algorithm: bump the sequence byte at $DF87; HL := $DF88; store to $DF11 and $DF85; BC := $0024; CALL
;       $DF3C (the lower-LC LDIR-across-banks helper) to copy the FCB into the scratch; DE := $DF88.
;   [RE] common front end of the random-record and search functions; keeps a private copy of the caller's
;       FCB in the BDOS bank so the file machinery can run with the LC banked in. [?]
; ----------------------------------------------------------------------
RANDREC_FIELD_RESET:
        LD HL,DEFERRED_COPY_FLAG
        INC (HL)
        INC HL
        LD (BDOS_PARAM_PTR),HL
        EX DE,HL
        LD (DEFERRED_COPY_DST),HL
        LD BC,$0024
        CALL $DF3C
        LD DE,DEFERRED_COPY_BUF
        RET
; ----------------------------------------------------------------------
; EMPTY_DIR_FCB -- Sentinel byte $E5 used as an empty/deleted directory-entry marker and zero-FCB source. [RE]
; ----------------------------------------------------------------------
EMPTY_DIR_FCB:
        DEFB    $E5
; ----------------------------------------------------------------------
; DRV_LOGIN_VECTOR -- 16-bit master drive vector at $BFBA. Despite the name, this build uses it as the
; READ-ONLY drive vector (set by BDOS_F_SETRO, tested by DRIVE_BIT_TEST, reported by BDOS_F_ROVEC). [RE]
; ----------------------------------------------------------------------
DRV_LOGIN_VECTOR:
        DEFB    "\0\0"
; ----------------------------------------------------------------------
; DRV_SELECT_VECTOR -- 16-bit working login/select vector at $BFBC (bit d set = drive d logged in). Read
; by BDOS_F_LOGINVEC, maintained by DRV_LOGIN_SCAN and BDOS_F_RESET_DRIVE. [RE]
; ----------------------------------------------------------------------
DRV_SELECT_VECTOR:
        DEFB    "\0\0"
; ----------------------------------------------------------------------
; DMA_ADDR -- 16-bit user DMA (disk transfer) address at $BFBE, default TBUFF ($0080). Set by BDOS_F_SETDMA
; / BDOS_F_DSKRESET and applied to the BIOS via RESTORE_USER_DMA. [RE]
; ----------------------------------------------------------------------
DMA_ADDR:
        DEFB    $80,$00
    ENT
; -------------------- end lower LC bank (back to $EA00 image top) --------------------
BDOS_IMAGE_END:                          ; first byte past the BDOS image ($EA00)

    IFNDEF CPM60_LINK  ; [link] master defines CPM60_LINK and owns this; standalone keeps it
    ; Image size from its bracketing labels, not a magic length, as in the 2.23-44K twin.
    ; The ENT above has closed the lower-bank DISP, so BDOS_IMAGE_END is the physical top
    ; of the image rather than a $Bxxx run address.
    ASSERT BDOS_IMAGE_END == $EA00
    SAVEBIN "CPM_BDOS.bin", $DC00, BDOS_IMAGE_END - $DC00
    ENDIF

; ----------------------------------------------------------------------
; BDOS work cells -- the 44K BDOS's cells, relocated.
;   The 60K BDOS is the 44K BDOS moved into the language card, and its scratch
;   cells moved with it by two constant offsets, one per bank:
;       upper bank  +$3FCE   (44K $9F41 -> 60K $DF0F)
;       lower bank  +$160D   (44K $A9B3 -> 60K $BFC0)
;   Those two deltas account for every cell with no exceptions, which is how
;   this naming was derived: the 44K twin's layout, order and field widths were
;   carried across and then checked against the addresses the 60K code actually
;   references. The names are therefore the SAME names as the 44K tree uses, so
;   a reader can move between the two.
;
;   The image ends at $BFC0 (DMA_ADDR is its last emitted storage), so unlike
;   the 44K -- where these cells are emitted zero bytes inside the image -- here
;   they are plain RAM above it. They are declared as a layout: one ORG at the
;   base, then a label per cell with its width carried in the arithmetic that
;   advances to the next. Labels emit no bytes, so this names the region without
;   adding any. [RE]
; ----------------------------------------------------------------------
        ORG $BFC0                     ; = 44K $A9B3 + $160D
DPB_WORK_PTR0:                           ; 2 bytes  (44K $A9B3)
        ORG DPB_WORK_PTR0 + 2
DEBLOCK_HSTREC_PTR0:                     ; 2 bytes  (44K $A9B5)
        ORG DEBLOCK_HSTREC_PTR0 + 2
DEBLOCK_HSTREC_PTR1:                     ; 2 bytes  (44K $A9B7)
        ORG DEBLOCK_HSTREC_PTR1 + 2
DIRBUF_PTR:                              ; 2 bytes  (44K $A9B9)
        ORG DIRBUF_PTR + 2
DPB_PTR:                                 ; 2 bytes  (44K $A9BB)
        ORG DPB_PTR + 2
REC_BYTE_OFFSET:                         ; 2 bytes  (44K $A9BD)
        ORG REC_BYTE_OFFSET + 2
ALLOC_VEC_PTR:                           ; 2 bytes  (44K $A9BF)
        ORG ALLOC_VEC_PTR + 2
DPB_SPT:                                 ; 2 bytes  (44K $A9C1)
        ORG DPB_SPT + 2
DPB_BSH:                                 ; 1 byte  (44K $A9C3)
        ORG DPB_BSH + 1
DPB_BLM:                                 ; 1 byte  (44K $A9C4)
        ORG DPB_BLM + 1
DPB_EXM:                                 ; 1 byte  (44K $A9C5)
        ORG DPB_EXM + 1
MAX_BLOCK_DSM:                           ; 2 bytes  (44K $A9C6)
        ORG MAX_BLOCK_DSM + 2
DPB_REC_PTR:                             ; 2 bytes  (44K $A9C8)
        ORG DPB_REC_PTR + 2
ALLOC_END_PTR:                           ; 2 bytes  (44K $A9CA)
        ORG ALLOC_END_PTR + 2
REC_SCAN_PTR:                            ; 2 bytes  (44K $A9CC)
        ORG REC_SCAN_PTR + 2
DPB_OFF:                                 ; 2 bytes  (44K $A9CE)
        ORG DPB_OFF + 2
DPB_XLT_PTR:                             ; 2 bytes  (44K $A9D0)
        ORG DPB_XLT_PTR + 2
DIR_DIRTY_FLAG:                          ; 1 byte  (44K $A9D2)
        ORG DIR_DIRTY_FLAG + 1
RW_DIRECTION_FLAG:                       ; 1 byte  (44K $A9D3)
        ORG RW_DIRECTION_FLAG + 1
DIR_MATCH_FLAG:                          ; 1 byte  (44K $A9D4)
        ORG DIR_MATCH_FLAG + 1
WRITE_TYPE_FLAG:                         ; 1 byte  (44K $A9D5)
        ORG WRITE_TYPE_FLAG + 1
DRV_SELECT_ARG:                          ; 1 byte  (44K $A9D6)
        ORG DRV_SELECT_ARG + 1
ALLOC_SLOT_INDEX:                        ; 1 byte  (44K $A9D7)
        ORG ALLOC_SLOT_INDEX + 1
DIR_CMP_LEN:                             ; 1 byte  (44K $A9D8)
        ORG DIR_CMP_LEN + 1
DIR_FCB_PTR:                             ; 4 bytes  (44K $A9D9)
        ORG DIR_FCB_PTR + 4
BLOCK_WIDTH_FLAG:                        ; 1 byte  (44K $A9DD)
        ORG BLOCK_WIDTH_FLAG + 1
DRV_RESTORE_FLAG:                        ; 1 byte  (44K $A9DE)
        ORG DRV_RESTORE_FLAG + 1
DRV_SAVED_DRIVE:                         ; 1 byte  (44K $A9DF)
        ORG DRV_SAVED_DRIVE + 1
DRV_SAVED_FCB_BYTE:                      ; 1 byte  (44K $A9E0)
        ORG DRV_SAVED_FCB_BYTE + 1
FCB_RECCOUNT:                            ; 1 byte  (44K $A9E1)
        ORG FCB_RECCOUNT + 1
FCB_EXTENT_MASKED:                       ; 1 byte  (44K $A9E2)
        ORG FCB_EXTENT_MASKED + 1
FCB_CURREC:                              ; 2 bytes  (44K $A9E3)
        ORG FCB_CURREC + 2
CUR_BLOCK_NUMBER:                        ; 2 bytes  (44K $A9E5)
        ORG CUR_BLOCK_NUMBER + 2
BLOCK_BASE_RECORD:                       ; 2 bytes  (44K $A9E7)
        ORG BLOCK_BASE_RECORD + 2
DEBLOCK_BYTE_OFF:                        ; 1 byte  (44K $A9E9)
        ORG DEBLOCK_BYTE_OFF + 1
CUR_RECORD:                              ; 1 byte  (44K $A9EA)
        ORG CUR_RECORD + 1
CUR_RECORD_HI:                           ; 1 byte  (44K $A9EB)
        ORG CUR_RECORD_HI + 1
REC_CACHE:                               ; 20 bytes  (44K $A9EC)
        ORG REC_CACHE + 20
BDOS_WORKCELLS_END:                      ; , first byte past the work cells

    ; Pin the relocated layout to the addresses the shipped code references.
    ASSERT DPB_SPT       == $BFCE
    ASSERT MAX_BLOCK_DSM == $BFD3
    ASSERT REC_CACHE     == $BFF9
    ASSERT BDOS_WORKCELLS_END == $C00D
